#!/usr/bin/env python3
"""
Add static ||| detail to all remaining plain bullet items in curriculum.ts
Uses exact string matching on the inner text of each bullet item.
"""

SEP = '|||'

# Map: exact inner text -> detail to append after |||
# All single quotes in detail are escaped with \'
DETAILS = {
    # FAR QUIZ ITEMS
    "The Federal Acquisition Roster \xe2\x80\x94 a list of approved contractors": "Incorrect. The FAR stands for the Federal Acquisition Regulation \xe2\x80\x94 the master rulebook governing how all U.S. federal agencies buy goods and services. There is no such thing as a \\'Federal Acquisition Roster.\\'",
    "The Federal Acquisition Regulation \xe2\x80\x94 the primary rulebook governing how the U.S. government buys goods and services": "Correct. The FAR (Federal Acquisition Regulation) is codified at 48 C.F.R. Chapter 1 and establishes uniform policies and procedures for all federal agencies. DoD supplements FAR with the DFARS for defense-specific requirements.",
    "The Forward Acquisition Rate \xe2\x80\x94 a cost estimating tool": "Incorrect. \\'Forward Acquisition Rate\\' is not a real term. The FAR is the Federal Acquisition Regulation. Forward Pricing Rate Agreements (FPRAs) are a related but separate concept \xe2\x80\x94 negotiated labor and overhead rates used to estimate future contract costs.",
    "A DoD-specific rule that only applies to defense contracts": "Incorrect, but close. This describes the DFARS (Defense Federal Acquisition Regulation Supplement), not the FAR itself. The FAR applies government-wide to all agencies. The DFARS supplements FAR specifically for DoD.",
    "The Contracting Officer\\'s Representative (COR)": "Correct. The COR is a government employee appointed in writing by the Contracting Officer to monitor contractor performance and serve as the technical interface between the program office and the contractor. CORs do not have contracting authority \xe2\x80\x94 only the CO can sign binding agreements.",
    "To slow down the process and create government jobs": "Incorrect. Competition in federal acquisition exists to protect taxpayer dollars and promote fair dealing. FAR Part 6 requires full and open competition unless a specific exception applies. Competition drives down price, improves quality, and prevents corruption.",
    "Because private companies demanded it": "Incorrect. Federal acquisition rules were created by Congress to protect public funds and ensure impartiality. Foundational laws include the Competition in Contracting Act (CICA) of 1984, the Federal Property and Administrative Services Act, and the Armed Services Procurement Act.",
    "To ensure public money is spent fairly, wisely, and with accountability to taxpayers and Congress": "Correct. The entire federal acquisition system exists to achieve best value while maintaining integrity and transparency. The FAR, DFARS, and the Competition in Contracting Act reflect Congress\\'s mandate to spend public money responsibly and maintain a competitive marketplace.",
    "Because the military prefers not to deal with industry directly": "Incorrect. The military works extensively with industry \xe2\x80\x94 that\\'s how most defense capabilities are acquired. Competition requirements exist for financial accountability and fairness, not because of any preference to avoid industry contact.",

    # WHAT DOD BUYS
    "Products (systems and equipment like aircraft and ships)": "Correct. Products are the most visible defense acquisition category \xe2\x80\x94 F-35 fighters, Virginia-class submarines, M1A2 tanks, GPS satellites, and body armor. These are often acquired through Major Defense Acquisition Programs (MDAPs) with ACAT I designation.",
    "Research & Development": "Correct. R&D (funded under RDT&E appropriations) is foundational to DoD acquisition. Budget activities run from basic research (6.1) through operational systems development (6.7). Understanding which RDT&E budget activity applies to a program phase is critical for acquisition planners.",
    "Services (people doing work: IT, maintenance, program support, etc.)": "Correct. Services represent the largest and fastest-growing segment of DoD spending \xe2\x80\x94 over $200B annually. This includes base operations, cybersecurity, and program management support. Services are acquired through IDIQs, GWACs, and agency-specific vehicles.",
    "Construction and real estate": "Correct. DoD is one of the world\\'s largest real property owners, managing hundreds of installations worldwide. Military construction (MILCON) is funded through a separate appropriation and includes barracks, runways, maintenance facilities, and family housing.",

    # IDIQ STRUCTURE
    "A contract for a single, fully defined delivery at a fixed price": "Incorrect. This describes a Firm Fixed Price (FFP) contract for a definite quantity \xe2\x80\x94 not an IDIQ. IDIQs (Indefinite Delivery/Indefinite Quantity) are used when the government cannot define the exact quantity or timing of future orders at award time.",
    "An umbrella contract that pre-qualifies contractors to do a category of work, with actual orders placed as task orders up to a ceiling value": "Correct. An IDIQ contract is an umbrella vehicle awarded to one (Single Award) or multiple (Multiple Award) contractors. The government commits only to a minimum guarantee and cannot exceed the ceiling. Real work is placed through individual task orders as requirements emerge.",
    "A contract type only used for construction projects": "Incorrect. IDIQs are used across all acquisition categories \xe2\x80\x94 services, products, IT, professional support, and some construction. They are not limited to construction. Construction has its own specialized vehicles (JOC, MATOC), but IDIQ is a general acquisition tool.",
    "A government-to-government agreement for shared services": "Incorrect. This describes an Interagency Agreement (IAA) or Economy Act agreement, not an IDIQ. IDIQs are competed contracts between the government and private industry.",
    "$200M \xe2\x80\x94 the full ceiling value": "Incorrect. The ceiling is the maximum total value of all task orders that can be placed \xe2\x80\x94 it does not guarantee any particular contractor that amount. In a 5-awardee IDIQ with a $200M ceiling, each contractor is guaranteed only the minimum and must compete for every task order.",
    "$40M \xe2\x80\x94 their proportional share among 5 awardees": "Incorrect. IDIQ contracts do not split the ceiling equally. The $200M ceiling is a government-side limit on total spending. Each awardee competes for individual task orders. One contractor could win 90% of orders; another could win nothing beyond the minimum guarantee.",
    "Only the minimum guarantee (often nominal, sometimes as little as $1)": "Correct. At IDIQ award, a contractor is legally guaranteed only the minimum \xe2\x80\x94 which by law must be at least $1 but in practice is often a few thousand dollars for large GWACs. Everything beyond that minimum requires winning individual task order competitions.",
    "Nothing until the IDIQ is exercised by the ordering agency": "Incorrect, but partially right conceptually. The government commits to a minimum guarantee at IDIQ award. Beyond that minimum, the contractor receives nothing until they win a task order competition. The minimum guarantee is the only legally committed obligation.",
    "The government may award to any awardee at its sole discretion": "Incorrect for MAIDIQ. Under FAR 16.505, Multiple Award IDIQ contracts require a \\'fair opportunity\\' process for task orders over the threshold. Every awardee must be given a fair opportunity to compete. Sole discretion applies only to Single Award IDIQs.",
    "Task orders rotate equally among all awardees": "Incorrect. There is no round-robin or rotation requirement in federal acquisition law. Under MAIDIQ, each task order requires a fair opportunity competition. The government selects the best value offeror for each task order.",
    "All awardees must receive a fair opportunity to be considered for each task order": "Correct. FAR 16.505(b) requires fair opportunity procedures for all task orders over the threshold. The contracting officer must notify all IDIQ awardees and evaluate their submissions using the factors established in the base IDIQ. Exceptions (urgency, one source) are narrow.",
    "Task orders go to the lowest bidder automatically": "Incorrect. Federal acquisition uses \\'best value\\' not lowest-bid for most task orders. While price is always considered, other factors like technical approach and past performance influence the award. Only very small simplified acquisitions may use price alone.",
    "IDIQ contracts are cheaper for the government to administer than standalone contracts": "Incorrect as a general statement. IDIQs reduce per-order procurement lead time but add administrative burden through task order competitions, performance monitoring across multiple awardees, and ceiling tracking. The efficiency gain is in speed and flexibility, not necessarily lower administrative cost.",
    "IDIQ vehicles allow the government to issue task orders quickly without running a full competition each time, saving months of acquisition lead time": "Correct. This is the primary strategic value of IDIQ vehicles. Instead of a 12-18 month standalone acquisition for each requirement, an agency can issue a task order competition under an existing IDIQ in 30-90 days. The base competition vets contractors once; task orders leverage that investment.",
    "Standalone contracts are illegal for service requirements": "Incorrect. Standalone contracts are fully legal for services and used frequently for large, well-defined requirements. There is no prohibition on standalone contracts for services.",
    "IDIQ vehicles give contractors more profit margin": "Incorrect. Contract type (not vehicle type) drives profit margin. IDIQs can be structured with FFP, cost-plus, T&M, or hybrid task order contract types. The underlying economics of each task order \xe2\x80\x94 not the IDIQ vehicle itself \xe2\x80\x94 determine contractor margin.",
    "Single Award IDIQs have higher ceilings than Multiple Award IDIQs": "Incorrect. There is no rule linking award type to ceiling value. Some of the largest IDIQ vehicles (OASIS+, ALLIANT 3, SEWP V) are multiple-award with multi-billion-dollar ceilings.",
    "Single Award IDIQs are only available to small businesses": "Incorrect. Single Award IDIQs are available to any contractor that wins the competition. A SAIDIQ gives one contractor all task orders without further competition. They require more government justification, particularly for awards over $112M in DoD.",
    "Single Award IDIQs give one contractor all task orders without further competition; Multiple Award IDIQs require competing for each task order among all awardees": "Correct. This is the fundamental structural difference. A Single Award IDIQ gives the winning contractor a monopoly on all work under that vehicle. A Multiple Award IDIQ (MAIDIQ) pools multiple qualified contractors and requires fair opportunity competition for each task order.",
    "Single Award IDIQs are administered by GSA; Multiple Award IDIQs are administered by the ordering agency": "Incorrect. Both types are administered by whichever contracting office runs the underlying vehicle \xe2\x80\x94 GSA, DoD, NASA, or any other agency. The administering office is not determined by award type.",

    # GOVERNMENT ROLES
    "The Program Manager": "Incorrect for the COR question. The Program Manager (PM) oversees overall program execution \xe2\x80\x94 cost, schedule, performance, and risk \xe2\x80\x94 but does not perform day-to-day contract surveillance. The COR specifically monitors contractor performance and acts as the technical interface, reporting observations to the CO.",
    "The Program Executive Officer (PEO)": "Incorrect. The PEO is a senior acquisition official who oversees a portfolio of related programs. The PEO provides strategic oversight and reviews major milestones \xe2\x80\x94 but does not conduct day-to-day contract monitoring. That operational-level role belongs to the COR.",
    "The Contracting Officer (CO)": "Incorrect for surveillance duties specifically. The CO has legal authority to enter into contracts but cannot personally monitor all contracts. The CO delegates surveillance duties to the COR in writing via a COR appointment letter. The CO remains the decision-making authority \xe2\x80\x94 the COR is the CO\\'s eyes and ears.",
    "Negotiates contract prices with contractors": "Incorrect for the COR role. Price negotiation is exclusively the Contracting Officer\\'s authority. The COR has no authority to commit the government financially or change contract terms. Informal COR negotiation (a \\'constructive change\\') creates unauthorized obligations.",
    "Monitors contractor performance day-to-day and serves as the technical interface between the program office and the contractor": "Correct. This is the COR\\'s core function. The COR reviews deliverables, validates contractor invoices by confirming work was performed, documents performance in CPARS, and maintains a COR file. The COR cannot commit the government to additional work \xe2\x80\x94 that requires a contract modification signed by the CO.",
    "Approves contractor invoices and processes payments": "Incorrect as stated. The COR certifies that goods or services were received before the CO approves payment. The finance office processes the actual disbursement. The COR\\'s role is technical verification, not final financial approval.",
    "Writes the Independent Government Cost Estimate (IGCE)": "Incorrect for COR. Writing the IGCE is primarily the responsibility of the Requirements Owner or program office technical staff. The COR focuses on performance monitoring after award. The IGCE is typically written by the government cost estimator or senior technical lead.",
    "DCAA writes requirements documents for major programs": "Incorrect. DCAA (Defense Contract Audit Agency) audits contractor costs \xe2\x80\x94 it does not write requirements documents. Requirements documents (ICD, CDD, CPD) are written by military requirements personnel through the JCIDS process.",
    "DCAA audits contractor costs and approves accounting systems on cost-reimbursable contracts": "Correct. DCAA is the DoD\\'s dedicated contract audit organization. On cost-type contracts, DCAA audits forward pricing proposals, reviews contractor accounting system adequacy, audits incurred cost submissions, and provides the CO with an audit opinion. An inadequate DCAA finding on an accounting system can disqualify a contractor from receiving cost-type contracts.",
    "DCAA manages IDIQ vehicles on behalf of the government": "Incorrect. DCAA does not manage contracts or vehicles \xe2\x80\x94 that is DCMA\\'s role. DCMA (Defense Contract Management Agency) is the DoD\\'s contract management and administration arm. The two often work together: DCAA audits, DCMA administers.",
    "DCAA provides independent cost estimates for Congressional reporting": "Incorrect. Independent cost estimates for Congressional reporting are provided by OSD CAPE (Cost Assessment and Program Evaluation), not DCAA. CAPE conducts independent cost estimates (ICEs) for major programs at milestone reviews. DCAA\\'s estimates are contract-specific audit opinions.",
    "The Program Manager\\'s office": "Incorrect for final contract decisions. The PM\\'s office drives requirements and manages technical execution, but the CO is the legal signatory with binding authority. The PM cannot unilaterally make binding contract decisions.",
    "The Service Acquisition Executive": "Incorrect for day-to-day contract decisions. The SAE is a senior political/career appointee who provides oversight of the acquisition enterprise for an entire military service. The SAE delegates authority downward to PEOs and PMs.",
    "The GAO (Government Accountability Office)": "Incorrect for contract decisions. GAO is a Congressional watchdog \xe2\x80\x94 it does not make contract decisions. GAO adjudicates bid protests but its role is oversight, not contract execution.",
    "The Department of Justice": "Incorrect. DOJ handles legal enforcement and litigation \xe2\x80\x94 it does not make contract award decisions. The contracting officer, acting under delegated authority, is the only government official who can legally bind the government to a contract.",
    "The Contracting Officer": "Correct. The CO (Contracting Officer) is the only government official with legal authority to enter into, administer, and terminate contracts on behalf of the government. This authority is delegated in writing via a \\'Warrant\\' (Certificate of Appointment under FAR 1.603).",
    "The prime contractor": "Incorrect. The prime contractor signs contracts with the government but does not make contract decisions on behalf of the government. The government\\'s contracting decisions rest exclusively with the Contracting Officer.",
    "Congress directly": "Incorrect for individual contract decisions. Congress shapes acquisition through legislation (NDAA, appropriations acts) but does not make individual contract award decisions. Congressional intent is implemented through executive agency regulations.",
    "The Program Executive Officer (PEO), who reports to the Service Acquisition Executive (SAE)": "Correct. This is the standard ACAT I chain of authority. The PEO is the MDA for ACAT II and III programs and reports to the SAE. For ACAT I programs, MDA is at the USD(A&S) level. The SAE is the service-level acquisition executive (e.g., ASA(ALT) for Army).",

    # APPROPRIATIONS
    "IT support is not an authorized use of O&M funds": "Incorrect. O&M funds are routinely used for IT support \xe2\x80\x94 help desk services, software licenses, network maintenance, and contractor labor supporting day-to-day operations. The issue with multi-year IT contracts is fund availability, not authorization.",
    "O&M funds have a 1-year obligation period, so a multi-year contract must be structured carefully to avoid obligating funds before they are available": "Correct. O&M appropriations expire for obligation at the end of the fiscal year (1-year money). A multi-year service contract must be structured to obligate only the funds available in each fiscal year \xe2\x80\x94 typically as base year plus option years. Obligating future-year funds before they are appropriated violates the Anti-Deficiency Act.",
    "O&M funds cannot be used for contractor services": "Incorrect. O&M funds are the primary funding mechanism for contracted services \xe2\x80\x94 program management support, IT services, facilities maintenance, and most service contracts are funded with O&M. The correct restriction is that O&M cannot fund capital acquisitions that should use Procurement funds.",
    "There is no issue \xe2\x80\x94 O&M funds are available indefinitely": "Incorrect. O&M funds are 1-year money \xe2\x80\x94 they must be obligated within the fiscal year in which they are appropriated. New obligations cannot be made after the end of the fiscal year. Failure to observe these rules violates the Anti-Deficiency Act.",
    "The Federal Acquisition Regulation (FAR)": "Incorrect for the specific O&M multi-year issue. The FAR governs acquisition procedures \xe2\x80\x94 it doesn\\'t directly restrict what funds can be used for what purpose. The binding authority on appropriations restrictions is the Anti-Deficiency Act (31 U.S.C. 1341) and the Purpose Statute.",
    "The Nunn-McCurdy Act": "Incorrect for appropriations purposes. Nunn-McCurdy (10 U.S.C. 2433) governs cost growth notification requirements for Major Defense Acquisition Programs. It requires Congressional notification when a program breaches cost thresholds. It does not govern appropriations timing.",
    "The Anti-Deficiency Act": "Correct. The Anti-Deficiency Act (31 U.S.C. 1341) prohibits federal officials from obligating funds in excess of or in advance of appropriations. Obligating next year\\'s O&M funds before they are appropriated violates the ADA. Violations can result in administrative disciplinary action and criminal penalties.",
    "The Economy Act": "Incorrect. The Economy Act (31 U.S.C. 1535) authorizes interagency acquisitions. It does not govern appropriations timing or the obligation of funds.",
    "Procurement": "Correct. Procurement (P) funds are used to buy end items \xe2\x80\x94 complete weapon systems, vehicles, aircraft, ships, and major equipment. They have a 3-year obligation period. If you\\'re buying something that will last more than 2 years and costs above the investment threshold (~$250K), it should be Procurement funds.",
    "Operations & Maintenance (O&M)": "Correct. O&M funds cover the day-to-day costs of running the military \xe2\x80\x94 contractor services, supplies, base operations, training, and maintenance. They are 1-year money. O&M is the largest DoD appropriation category by dollar volume and the most commonly used for service contracts.",
    "Research, Development, Test & Evaluation (RDT&E)": "Correct. RDT&E funds support the full spectrum of defense research and development, from basic science (6.1) through system development and demonstration (6.5). They have a 2-year obligation period.",
    "Military Personnel (MILPERS)": "Correct. MILPERS funds pay for military salaries, housing allowances, and personnel entitlements. They are strictly for military members \xe2\x80\x94 civilian pay comes from O&M. MILPERS are 1-year funds.",
    "They roll over automatically to next fiscal year": "Incorrect. Annual appropriations (O&M, MILPERS) do not roll over. At the end of the fiscal year, unobligated annual funds expire \xe2\x80\x94 the government loses the ability to commit them to new contracts. \\'Use it or lose it\\' pressure at fiscal year end is a real phenomenon in DoD acquisition.",
    "They can be carried over for up to 3 years": "Incorrect as stated for O&M. O&M funds must be OBLIGATED within 1 year. They can be EXPENDED (paid out) for 5 years total. After 5 years, the funds are cancelled. Procurement funds have a 3-year obligation period.",
    "They expire and can no longer be obligated for new work": "Correct. When an annual appropriation expires (end of fiscal year for O&M/MILPERS; after 3 years for Procurement), it moves into \\'expired\\' status \xe2\x80\x94 during which it can still pay existing obligations but cannot fund new work. After 5 years total, the account is cancelled.",
    "They are returned to Congress for reallocation": "Incorrect. Expired funds remain in Treasury accounts in expired status. Congress does not reallocate individual expired appropriations to agencies mid-cycle.",

    # ADAPTIVE ACQUISITION FRAMEWORK
    "A single, mandatory lifecycle all DoD programs must follow": "Incorrect. The current AAF (Adaptive Acquisition Framework), established by DoDI 5000.02 (2020), provides six distinct pathways. Different program types follow different paths \xe2\x80\x94 a software product follows the Software Acquisition Pathway, not the Major Capability Acquisition path.",
    "A DoD policy framework with six distinct acquisition pathways tailored to different types of programs": "Correct. The AAF provides six pathways: (1) Major Capability Acquisition, (2) Middle Tier \xe2\x80\x94 Rapid Prototyping, (3) Middle Tier \xe2\x80\x94 Rapid Fielding, (4) Software Acquisition, (5) Defense Business Systems, and (6) Acquisition of Services. Each pathway has different oversight, documentation, and speed requirements.",
    "A Congressional mandate requiring DoD to reduce acquisition timelines by 50%": "Incorrect. The AAF is a DoD policy framework, not a specific Congressional mandate. It was established through DoD\\'s own policy issuances under the authority of the Under Secretary of Defense for Acquisition and Sustainment.",
    "A GSA-managed contract vehicle for adaptive IT services": "Incorrect. The AAF is a DoD acquisition policy framework \xe2\x80\x94 it is not a contract vehicle, not GSA-managed, and not specific to IT.",
    "The program receives its initial funding and begins studying alternatives": "Incorrect. Receiving initial funding and studying alternatives happens during the Materiel Solution Analysis (MSA) phase \xe2\x80\x94 before Milestone A. At Milestone B, the program enters Engineering & Manufacturing Development (EMD).",
    "The program completes operational testing and begins Full Rate Production": "Incorrect. Completing operational testing (IOT&E) and entering Full Rate Production occurs at the FRP Decision Review \xe2\x80\x94 after Milestone C. Milestone B is earlier in the lifecycle.",
    "The MDA approves entry into Engineering & Manufacturing Development \xe2\x80\x94 the system is built and tested": "Correct. Milestone B is the most significant acquisition decision for most programs. The MDA reviews the program\\'s readiness to begin detailed design, fabrication, and developmental testing. An APB is established at this point.",
    "The government issues the first task order under the program\\'s IDIQ contract": "Incorrect. Milestone B is an internal government decision gate \xe2\x80\x94 it approves the program\\'s entry into the EMD phase. Contract actions may follow from Milestone B, but the milestone itself is the MDA\\'s approval of program readiness.",

    # DOCUMENTS
    "The Acquisition Program Baseline (APB)": "Correct. The APB is established at Milestone B and documents the program\\'s approved cost, schedule, and performance parameters. Breaching APB thresholds triggers Nunn-McCurdy reporting (for MDAPs) and requires MDA approval to restructure.",
    "The Capability Development Document (CDD)": "Correct. The CDD is the JCIDS requirements document that bridges the capability gap analysis and the detailed system requirements. It is typically validated before Milestone B and defines Key Performance Parameters (KPPs), Key System Attributes (KSAs), and Additional Performance Attributes (APAs).",
    "The Initial Capabilities Document (ICD)": "Correct. The ICD is the first formal requirements document in the JCIDS process. It documents the capability gap, the mission context, and potential approaches. Typically validated before Milestone A, it drives the Analysis of Alternatives (AoA).",
    "The Analysis of Alternatives (AoA)": "Correct. The AoA is an analytical study that evaluates alternative approaches to fill a capability gap. It assesses each alternative\\'s operational effectiveness, suitability, cost, schedule, and risk. Typically completed during the MSA phase, it informs the Milestone A decision.",

    # PATHWAYS
    "Major Capability Acquisition (MCA)": "Correct. The MCA pathway is used for complex, long-term programs developing new military capabilities. It involves Milestones A, B, and C, with full JCIDS documentation and ACAT designation. USD(A&S) has MDA for ACAT I programs. Examples: F-35, CVN-21, GBSD.",
    "Middle Tier \xe2\x80\x94 Rapid Fielding": "Correct. The Middle Tier Rapid Fielding pathway (Section 804 of FY2016 NDAA) is used to field proven capabilities with minimal development risk within 5 years. It bypasses some traditional milestone reviews for speed. Appropriate for commercial technology and productionized items with low technical risk.",
    "Software Acquisition Pathway": "Correct. The Software Acquisition Pathway (DoDI 5000.87) is designed for software-intensive programs using Agile, DevSecOps, and continuous delivery practices. It replaces the traditional hardware-centric lifecycle with iterative cycles and uses a Life Cycle Cost Estimate (LCCE) instead of an APB.",
    "Acquisition of Services": "Correct. The Acquisition of Services pathway governs acquisition of professional and technical services \xe2\x80\x94 program support, IT services, logistics. It emphasizes performance-based service contracts, pre-competed IDIQ vehicles, and the 7-step services acquisition process. Services account for over 50% of DoD contract spending.",

    # MSA
    "Because the government signs binding fixed-price contracts during MSA": "Incorrect. MSA does not typically involve binding production contracts. MSA involves studies, analyses, and potentially technology demonstrations. The binding commitments come later, at Milestone B (entering EMD) and Milestone C (entering production).",
    "Because Congress sets the budget for the entire program during MSA": "Incorrect. Congress appropriates funds through annual legislation, not a one-time MSA determination. Cost estimates during MSA are rough and uncertain. The APB isn\\'t established until Milestone B.",
    "Because requirements, design approach, and technology choices made early determine the complexity and cost of everything that follows \xe2\x80\x94 changing them later is exponentially more expensive": "Correct. Studies show 70-80% of a program\\'s life cycle cost is locked in by the end of the design phase. Adding requirements after EMD begins, or discovering technology limitations during production, creates delays and cost overruns that are orders of magnitude more expensive than getting it right during MSA.",
    "Because contractors set their prices during the MSA phase and cannot change them": "Incorrect. Contractors typically do not set binding prices during MSA. The major contract award (for EMD) comes after Milestone B. Prices are negotiated for each contract action.",

    # MILESTONES
    "Milestone A \xe2\x80\x94 Entry into Technology Maturation & Risk Reduction (TMRR)": "Correct. Milestone A is the entry point into the TMRR phase. The MDA approves the program\\'s approach to maturing technology and reducing risk before committing to a specific design. Key inputs: ICD validation, AoA completion, technology readiness assessments.",
    "Milestone B \xe2\x80\x94 Entry into Engineering & Manufacturing Development (EMD)": "Correct. Milestone B is often the most consequential acquisition decision. The MDA approves the program\\'s plan to develop, fabricate, and test the system. Key inputs: CDD validation, systems engineering plan, APB establishment, CAPE independent cost estimate for ACAT I.",
    "Milestone C \xe2\x80\x94 Entry into Production & Deployment (Low-Rate Initial Production authorized)": "Correct. Milestone C authorizes Low-Rate Initial Production (LRIP) \xe2\x80\x94 a limited production run before full-rate production. The MDA reviews developmental test results and approves the production contract strategy. LRIP units are used for operational testing (IOT&E) and initial fielding.",
    "Full-Rate Production (FRP) Decision \xe2\x80\x94 After IOT&E completion": "Correct. The FRP Decision Review is held after operational testing (IOT&E) is complete. The MDA approves full production. This is not technically a \\'Milestone\\' in the traditional A/B/C sense \xe2\x80\x94 it\\'s a separate decision review.",

    # PRICING
    "Accept the proposal since ceiling rates are guidelines, not hard limits": "Incorrect. IDIQ ceiling rates are contractually binding \xe2\x80\x94 they represent the maximum billable rate for each labor category. A contractor proposing rates above the established ceiling is non-compliant.",
    "The proposal is non-compliant \xe2\x80\x94 ceiling rates are contractually binding and the contractor cannot exceed them without a contract modification": "Correct. IDIQ labor category ceiling rates establish the maximum rate the contractor may bill. Proposing above the ceiling rate for a task order is a material non-compliance requiring either rate reduction or a formal contract modification.",
    "Request a waiver from DCAA before accepting": "Incorrect. DCAA does not grant waivers for non-compliant proposals. DCAA audits cost proposals and provides opinions to the CO. Waivers for non-compliance would be a CO decision \xe2\x80\x94 not a DCAA function.",
    "The contracting officer may accept if the work is highly specialized": "Incorrect. Specialization does not override contractual ceiling rates. If work requires skills beyond established LCATs, the solution is to add a new LCAT via contract modification, not to waive the ceiling rate.",
    "The contractor is using an incorrect estimating methodology": "Incorrect for LCAT over-leveling. Over-leveling is a pricing integrity concern where the contractor assigns work to higher-level labor categories than the work requires, driving up cost without improving performance.",
    "The contractor is proposing an inflated labor mix \xe2\x80\x94 over-leveling LCATs to drive up cost without improving performance": "Correct. Over-leveling (or \\'labor-loading\\') involves proposing Senior Engineer-level hours for work that could be performed by Mid-level or Junior staff. On a T&M or cost-plus contract, this directly inflates billable cost. The CO and DCAA will scrutinize the labor mix during cost or price analysis.",
    "The direct labor rates are too low for Level III engineers": "Incorrect for over-leveling. Low rates would benefit the government \xe2\x80\x94 that would be under-pricing, not over-leveling. The over-leveling problem is the opposite: rates are appropriate for the category, but the wrong (too senior) category is being proposed for the work.",
    "The proposal violates TINA because it uses parametric estimating": "Incorrect. TINA violations involve submitting defective cost or pricing data \xe2\x80\x94 not using parametric methods. Parametric estimating is a legitimate and commonly used technique.",

    # EVM METHODS
    "Method 2: AC + (BAC - EV) \xe2\x80\x94 Remaining work at original budget rates": "Correct. This EAC formula assumes the cost overruns to date were anomalies and remaining work will proceed at originally planned rates. It is optimistic and appropriate only when the PM has strong evidence that past overruns were non-recurring. Programs with sustained CPI < 1.0 should generally not use this method.",
    "Method 1/3: BAC / CPI \xe2\x80\x94 Remaining work at current cost efficiency": "Correct. This is the most commonly used and most statistically reliable EAC formula. Empirical research (Christensen studies) shows CPI rarely improves significantly after the 20% completion point. EAC = BAC/CPI is required for government EAC validation in most DoD programs.",
    "Method 4: AC + [(BAC-EV)/(CPI\xd7SPI)] \xe2\x80\x94 Combined cost and schedule inefficiency": "Correct. This composite EAC formula accounts for both cost (CPI) and schedule (SPI) efficiency \xe2\x80\x94 appropriate when schedule pressure is driving cost inefficiency (overtime, surge staffing). It is the most pessimistic of the standard EAC methods and typically produces the highest (most conservative) estimate.",

    # COST BUILDUP
    "Direct Labor Rate (DLR) \xe2\x80\x94 base hourly rate for the labor category": "Correct. The DLR is the foundation of cost-type contract pricing. It represents the base hourly compensation for a specific labor category (e.g., Senior Systems Engineer: $85/hr). All indirect costs (fringe, overhead, G&A) and fee are applied on top of the DLR.",
    "Fringe Benefits \xe2\x80\x94 applied to DLR (health, retirement, FICA, leave)": "Correct. Fringe is an indirect cost pool applied to direct labor. It typically includes FICA (7.65%), health/dental/vision insurance, 401k match, paid leave, and workers\\' compensation. Fringe rates for large contractors run 25-40% of direct labor \xe2\x80\x94 one of the largest cost drivers.",
    "Overhead \xe2\x80\x94 applied to direct labor within a business unit": "Correct. Overhead covers costs of running a business division not directly attributable to a specific contract \xe2\x80\x94 division management, facility costs, IT infrastructure, training. Overhead rates vary by business unit and are subject to DCAA Rate Agreements.",
    "G&A \xe2\x80\x94 applied to Total Cost Input (all of the above)": "Correct. General and Administrative (G&A) expense covers enterprise-wide costs \xe2\x80\x94 CEO, CFO, legal, HR, corporate marketing. G&A is typically applied to Total Cost Input. G&A rates run 10-20% for large defense contractors and is the last indirect rate layer before fee.",
    "Fee / Profit \xe2\x80\x94 applied to total estimated cost as final layer": "Correct. Fee (on cost-type contracts) or profit (on fixed-price) is negotiated between the CO and contractor. FAR 15.404-4 provides fee guidelines. For CPFF contracts, fee is fixed at negotiation. For CPAF, additional fee can be earned based on performance.",

    # DCAA AUDITS
    "Pre-Award Accounting System Survey (before cost-type contract award)": "Correct. Before a contractor can receive a cost-type contract, DCAA reviews whether their accounting system can adequately track and segregate costs by contract. An inadequate accounting system is a disqualifying condition. DFARS 252.242-7006 defines the 18 criteria for an adequate accounting system.",
    "Forward Pricing Rate Audit (supporting FPRA before/at award)": "Correct. DCAA audits proposed indirect rates (fringe, overhead, G&A) and direct labor rates to support Forward Pricing Rate Agreements (FPRAs). These rates are then used as the basis for pricing all subsequent proposals under that contractor.",
    "Provisional Billing Rate Review (during contract performance)": "Correct. During performance, contractors bill at Provisional Billing Rates (PBRs) \xe2\x80\x94 estimated indirect rates \xe2\x80\x94 until actual rates are determined at year end. DCAA reviews these rates periodically to ensure they are reasonable and consistent with actual cost trends.",
    "Incurred Cost Submission (ICS) Audit (after each fiscal year end)": "Correct. After each fiscal year, contractors submit an Incurred Cost Submission (ICS) \xe2\x80\x94 an accounting of all actual costs incurred on government contracts. DCAA audits the ICS to determine final actual indirect rates, which may result in adjustments to prior billings.",

    # CONTRACT TYPES
    "Traditional FAR/DFARS Contract (full CAS, DFARS, TINA, competition)": "Correct. Traditional FAR/DFARS contracts carry the full weight of government procurement law \xe2\x80\x94 CAS for cost-type, DFARS clauses, TINA certified cost or pricing data requirements over $2M, and mandatory competition under FAR Part 6. These provide maximum oversight but maximum administrative burden.",
    "FAR Part 12 Commercial Item (reduced clauses; no CAS; no certified cost data)": "Correct. FAR Part 12 commercial item acquisitions use a streamlined clause set. Contractors are not required to submit certified cost or pricing data, CAS does not apply, and standard commercial terms are accepted. Preferred for COTS and commercial services but requires a determination of commerciality.",
    "Other Transaction Authority (no FAR/DFARS/CAS; negotiated terms only)": "Correct. OTAs are authorized under 10 U.S.C. 4021-4022 and allow DoD to negotiate agreements without FAR/DFARS constraints. They are designed to attract non-traditional defense contractors and accelerate prototyping and fielding. OTAs cannot be used for traditional services or routine supplies.",
    "Simplified Acquisition Procedures (below $250K; three quotes; minimal docs)": "Correct. SAP applies to purchases below the Simplified Acquisition Threshold ($250K standard). The CO can use simplified competition \xe2\x80\x94 typically three competitive quotes \xe2\x80\x94 with minimal documentation. This allows rapid procurement for routine, lower-dollar requirements.",
    "Micro-Purchase / Government Purchase Card (below $10K; no competition required)": "Correct. Micro-purchases (below $10K generally) can be made by government purchase card without competition under FAR 13.2. No contract is required \xe2\x80\x94 the purchase is made directly on a government credit card. This is the fastest acquisition method.",

    # OASIS+
    "Optimized Acquisition Services \xe2\x80\x94 IT systems only": "Incorrect. OASIS+ stands for One Acquisition Solution for Integrated Services Plus. It is NOT limited to IT \xe2\x80\x94 it covers professional and technical services including program management, management consulting, engineering, scientific, financial, and logistics support. SEWP V is the GSA IT-focused GWAC.",
    "One Acquisition Solution for Integrated Services Plus \xe2\x80\x94 professional and technical services across all disciplines": "Correct. OASIS+ is GSA\\'s flagship professional and technical services GWAC. Awarded in 2023-2024, it replaced the original OASIS contract with an expanded scope covering management consulting, program management support, engineering, R&D, data analytics, logistics, and more.",
    "Operations and Sustainment Integrated Services \xe2\x80\x94 logistics and supply chain only": "Incorrect. No GWAC uses the abbreviation OASIS+ to mean \\'Operations and Sustainment Integrated Services.\\' OASIS+ is a GSA GWAC for professional and technical services \xe2\x80\x94 not a logistics-only vehicle.",
    "Provides a contract vehicle that agencies use independently": "Incorrect as a description of AAS-D. AAS-D\\'s defining characteristic is that GSA manages the entire acquisition on behalf of the customer \xe2\x80\x94 acting as the contracting office. This is \\'assisted acquisition\\' \xe2\x80\x94 fundamentally different from simply providing a vehicle.",
    "Manages the entire acquisition process on behalf of the customer agency, serving as the contracting office": "Correct. GSA\\'s Assisted Acquisition Services - Defense (AAS-D) is an assisted acquisition service where GSA acts as the buying agency \xe2\x80\x94 managing the full acquisition lifecycle from requirements to award to contract administration \xe2\x80\x94 on behalf of DoD and other federal customers.",
    "Only supports civilian agencies, not DoD": "Incorrect. AAS-D is specifically designed for DoD customers. The \\'Defense\\' designation in AAS-D indicates the primary customer base.",

    # GWAC BASICS
    "Can only be used by the agency that established it": "Incorrect for GWACs. Government-Wide Acquisition Contracts \xe2\x80\x94 by definition \xe2\x80\x94 are available to all federal agencies. That government-wide accessibility is their defining feature.",
    "Is available for use by any federal agency as an ordering agency": "Correct. GWACs are authorized under 40 U.S.C. 11314 and are open to all federal agencies. This cross-agency accessibility allows smaller agencies without acquisition expertise to leverage GWACs managed by agencies like GSA or NIH.",
    "Does not require competition at the task order level": "Incorrect. Most GWACs require fair opportunity competition at the task order level under FAR 16.505. Awardees must be given a fair opportunity to submit offers for each task order. Exceptions are narrow.",
    "Limits the total value of task orders under any GWAC": "Incorrect. There is no universal statutory cap on GWAC total value \xe2\x80\x94 individual GWACs have their own ceiling values set at award.",
    "Provides statutory authority for one agency to procure services or supplies from another federal agency": "Correct. The Economy Act (31 U.S.C. 1535) authorizes interagency acquisitions \xe2\x80\x94 one agency using another agency\\'s contracting resources or purchasing on their behalf.",
    "Requires competition for all orders over $250K": "Incorrect for the Economy Act specifically. The Economy Act governs the relationship between federal agencies in interagency acquisitions \xe2\x80\x94 it does not set competition thresholds. Competition requirements at the ordering level are governed by the individual GWAC\\'s terms and FAR 16.505.",
    "Civilian agencies only": "Incorrect for AAS-D. AAS-D is specifically a defense-focused assisted acquisition service. DoD components regularly use AAS-D to leverage GSA\\'s contracting expertise.",
    "DoD agencies requiring assisted acquisition support, particularly for IT and professional services": "Correct. AAS-D serves DoD customers who need a skilled contracting office to manage acquisitions on their behalf \xe2\x80\x94 particularly valuable for program offices that lack acquisition expertise or contracting capacity.",
    "Small businesses seeking to enter the defense market": "Incorrect. AAS-D is a customer-facing service for government agencies \xe2\x80\x94 not a vehicle for small businesses to enter the market. Small businesses participate as contractors; AAS-D is used by government agencies as the buyer-side mechanism.",

    # GWAC RISKS
    "Paying too high a price due to lack of competition": "Incorrect as primary GWAC risk. GWACs are pre-competed vehicles. The primary ordering-level risks are: scope creep (ordering work outside the GWAC\\'s scope), improper use of the vehicle, and bypassing fair opportunity requirements.",
    "Placing task orders for work outside the scope of the GWAC base contract": "Correct. This is the most legally significant risk when using GWACs. A task order placed for work outside the scope of the base IDIQ constitutes an unauthorized procurement \xe2\x80\x94 potentially triggering a protest or legal challenge.",
    "Failing to meet small business goals": "Correct. Many GWACs have small business set-aside pools. Ordering agencies that consistently bypass small business pools may face scrutiny from the SBA and their agency\\'s Office of Small Business Programs.",

    # VEHICLES
    "A large-business IT GWAC for complex solutions": "Correct for ALLIANT 2. ALLIANT 2 is a GSA GWAC for complex IT solutions, limited to large businesses. ALLIANT 3 is in procurement as of 2024. ALLIANT 2 Small Business is the companion vehicle. These vehicles cover IT services, systems integration, cybersecurity, and cloud solutions.",
    "A small business IT GWAC with 8(a), WOSB, SDVOSB, and HUBZone pools": "Correct for ALLIANT 2 Small Business or SEWP V small business. These GWACs organize small business participation into socioeconomic pools: 8(a) (SBA-certified disadvantaged businesses), WOSB (women-owned), SDVOSB (service-disabled veteran-owned), and HUBZone.",
    "A professional services GWAC for all service disciplines": "Correct for OASIS+. OASIS+ is GSA\\'s flagship professional services GWAC covering management consulting, program management, engineering, logistics, data analytics, and more \xe2\x80\x94 for both large and small businesses across multiple pools.",
    "When the acquisition is under $250K and competition is not required": "Incorrect. AAS-D is used for significant acquisitions \xe2\x80\x94 particularly complex services benefiting from GSA\\'s contracting expertise. Small purchases under the SAT would typically be handled through simplified acquisition or purchase card.",
    "When the program office\\'s contracting office lacks capacity, expertise, or bandwidth to run the full acquisition": "Correct. This is the primary driver for using AAS-D. Program offices with technical expertise but limited acquisition personnel benefit from GSA\\'s experienced acquisition teams managing the process.",
    "When competition is not desired to protect the incumbent contractor": "Incorrect. AAS-D does not facilitate non-competitive awards as a matter of policy. Any acquisition through AAS-D must still comply with competition requirements.",

    # TASK ORDER COMPONENTS
    "The technical requirements for the specific task order": "Correct. The Task Order SOW/PWS/SOO describes what the contractor will actually do \xe2\x80\x94 the scope, deliverables, performance standards, and period of performance for that specific task order.",
    "The mutual terms under which the ordering agency will use the GWAC, including funding transfer and responsibilities": "Correct. An Interagency Agreement (IAA) \xe2\x80\x94 including a MIPR or Economy Act Order \xe2\x80\x94 establishes the terms of the relationship between the ordering agency and the contracting agency, covering funding transfer and responsibilities.",
    "The competition strategy for individual task orders": "Correct. The Acquisition Plan or Task Order Acquisition Strategy defines how the agency will conduct fair opportunity for a specific task order \xe2\x80\x94 factors, evaluation methodology, oral presentation requirements, past performance approach, and price reasonableness determination.",

    # REA PROCESS
    "Government directs change (formal or constructive)": "Correct. The changes clause process begins when the government directs a change \xe2\x80\x94 either through a formal written order under the Changes clause (FAR 52.243-1 through -4) or through constructive change (government actions that effectively change the contract without formal direction).",
    "Contractor submits REA with entitlement and cost proposal": "Correct. The contractor submits a Request for Equitable Adjustment (REA) that establishes: (1) entitlement \xe2\x80\x94 the legal basis for why a change occurred, and (2) the cost/schedule impact. The REA is not a certified claim \xe2\x80\x94 it is a negotiation opener.",
    "DCAA audits REA cost proposal (if >$2M)": "Correct. For cost proposals over $2M, DCAA typically audits the REA cost proposal to assess cost reasonableness, allocability, and allowability. The audit opinion gives the CO a basis for evaluating the contractor\\'s claimed costs before negotiation.",
    "CO and contractor negotiate equitable adjustment": "Correct. After DCAA audit (if applicable), the CO and contractor negotiate the amount and terms of the equitable adjustment \xe2\x80\x94 the change in contract price and/or schedule to account for the directed change.",
    "Bilateral modification definitizes the change (ideal outcome)": "Correct. A bilateral modification (signed by both the CO and contractor) is the preferred outcome \xe2\x80\x94 it definitizes the change and prevents future disputes. Once signed, the contractor cannot re-open the REA for additional compensation.",
    "If failed: REA converts to certified Claim; CO issues Final Decision": "Correct. If REA negotiation fails, the contractor may convert the REA to a certified Claim under the Contract Disputes Act (CDA). The CO issues a Contracting Officer\\'s Final Decision (COFD), which can be appealed to the Armed Services Board of Contract Appeals (ASBCA) or the Court of Federal Claims.",

    # FAIR OPPORTUNITY (2nd set)
    "All awardees must receive a fair opportunity to be considered": "Correct. FAR 16.505(b)(1) requires fair opportunity procedures for task orders over the threshold. Each MAIDIQ awardee must be notified, given the opportunity to submit a proposal, and evaluated using the criteria established in the base IDIQ.",
    "Task orders under $150,000 require full and open competition": "Incorrect. Task orders under $150,000 are often exempt from fair opportunity requirements \xe2\x80\x94 the CO may award at their discretion. It\\'s orders OVER $3,500 (and especially over $150,000 for civilian agencies, $6M for DoD) that trigger increasing fair opportunity formality.",
    "The incumbent contractor receives right of first refusal": "Incorrect. There is no statutory right of first refusal for incumbent contractors on MAIDIQ task orders. All awardees must receive fair opportunity. While past performance is a legitimate evaluation factor, it does not give the incumbent a contractual preference.",

    # A&AS
    "Management and Professional Support Services": "Correct. This is one of the four A&AS (Advisory and Assistance Services) categories defined in FAR 37.2. It covers management analysis, organizational studies, training, and professional support. Defense agencies use this category for program management support and strategic planning assistance.",
    "Studies, Analyses, and Evaluations": "Correct. This A&AS category covers independent research, operational analysis, technical evaluations, and studies. It includes policy analysis, program assessments, and alternatives analysis \xe2\x80\x94 work that informs government decisions without directly executing them.",
    "Engineering and Technical Services": "Correct. This A&AS category covers technical expertise supporting government programs \xe2\x80\x94 systems engineering, technical review, test support, and engineering advisory services. It is the most commonly used A&AS category in DoD acquisition programs.",
    "A&AS-D (Digital)": "Incorrect. The correct expansion is A&AS-D = Advisory and Assistance Services \xe2\x80\x94 Defense (or specifically, GSA\\'s AAS-D = Assisted Acquisition Services - Defense). There is no \\'Digital\\' designation in the standard A&AS taxonomy.",
    "GWACs have higher minimum guarantees than agency IDIQs": "Incorrect. GWAC minimum guarantees are often very low \xe2\x80\x94 sometimes $1 per awardee \xe2\x80\x94 to minimize the government\\'s financial commitment while maintaining a large awardee pool. The minimum guarantee comparison between GWACs and agency IDIQs varies by vehicle.",
    "GWACs are available to all federal agencies; agency IDIQs are limited to named awardees": "Partially correct but conflated. GWACs are available to all federal agencies as ordering agencies. Agency IDIQs are typically limited to the establishing agency or named ordering activities. The key difference is who can ORDER \xe2\x80\x94 not who can hold the contract.",

    # OTA
    "OTAs have lower dollar thresholds": "Incorrect. OTAs do not have lower thresholds than FAR contracts \xe2\x80\x94 in fact, they are often used for larger, more complex prototype and production programs. The value of OTAs is regulatory flexibility, not cost threshold reduction.",
    "OTAs bypass standard FAR procurement regulations": "Correct. OTAs are authorized under 10 U.S.C. 4021-4022. They are explicitly not subject to the FAR, DFARS, or most standard procurement regulations. This allows DoD to negotiate customized agreements and attract non-traditional defense contractors. However, OTAs require a prototype purpose.",
    "OTAs require Congressional approval": "Incorrect. OTA authority is already granted by Congress through statute (10 U.S.C. 4021). Individual OTA agreements do not require separate Congressional approval.",
    "OTAs are only available to small businesses": "Incorrect. OTAs are available to any contractor. One requirement is that at least one \\'non-traditional defense contractor\\' participates. Large defense contractors can and do use OTAs when working with non-traditional partners.",

    # FSS
    "A guaranteed revenue source for qualified contractors": "Incorrect. Being on the Federal Supply Schedule does not guarantee revenue. Schedule contractors must still market their offerings and compete for individual orders. Many schedule holders receive little or no government business.",
    "A pre-competed vehicle available only to defense agencies": "Incorrect. The GSA Multiple Award Schedule (MAS/FSS) is available to all federal agencies \xe2\x80\x94 civilian and defense. It is managed by GSA and is government-wide.",
    "A marketing platform with pre-negotiated commercial terms available to all federal agencies": "Correct. The GSA Multiple Award Schedule (MAS) is a long-term contract vehicle with pre-established pricing that any federal agency can use. Contractors list their products and services at pre-negotiated prices, and agencies can order directly.",
    "An IDIQ requiring annual task order competitions": "Incorrect. MAS orders are simplified \xe2\x80\x94 for orders below $10K, the ordering agency can select any MAS contractor; for orders over $10K, the agency must provide fair opportunity to three or more MAS awardees. There is no annual re-competition requirement.",

    # AIR FORCE
    "An Army-specific IDIQ for base operations services": "Incorrect. AFICC (Air Force Installation Contracting Center) is an Air Force contracting organization \xe2\x80\x94 not Army. AFICC manages Air Force installation contracting across all CONUS Air Force installations.",
    "GSA\\'s flagship GWAC for complex professional services including program management and engineering": "Correct for OASIS+. OASIS+ is GSA\\'s largest and most comprehensive professional services GWAC. Recompeted in 2023-2024, it provides access to a large pool of qualified contractors for complex, integrated professional services across all disciplines.",
    "A NASA GWAC for IT products and services": "Correct. SEWP (Solutions for Enterprise-Wide Procurement) is a NASA-managed GWAC for IT products and services \xe2\x80\x94 hardware, software, and related services. SEWP V is the current generation, with very fast ordering timelines (24-48 hours for simple orders).",
    "A DoD-only vehicle for classified program support": "Incorrect. Major GWACs (OASIS+, SEWP, ALLIANT) are unclassified and available to all agencies. Classified program acquisitions typically use separate, program-specific vehicles.",

    # AFICC
    "Processing simplified acquisitions under the Simplified Acquisition Threshold": "Incorrect for AFICC ESS specifically. Base-level contracting squadrons handle simplified acquisitions for individual installations. AFICC Enterprise Sourcing Squadrons focus on enterprise-level, higher-value acquisitions across the Air Force.",
    "Large-dollar, enterprise-level acquisitions across installations and functional areas": "Correct. AFICC Enterprise Sourcing Squadrons (ESS) specialize in large, complex acquisitions spanning multiple Air Force installations or functional areas \xe2\x80\x94 base operations support, IT services, professional services.",
    "Classified acquisition programs for AFSOC and special operations": "Incorrect. AFICC ESS is not specifically a classified AFSOC vehicle. AFSOC has its own acquisition infrastructure for classified requirements. ESS focuses on enterprise services, not classified special operations.",
    "Small business set-aside competitions at individual base levels": "Incorrect for AFICC ESS. Small business set-asides at individual bases are managed by base-level contracting squadrons. ESS focuses on large enterprise acquisitions.",
    "AFICC / Enterprise Sourcing Squadrons": "Correct. AFICC (Air Force Installation Contracting Center) ESS are the specialized acquisition organizations within AFICC that manage enterprise-wide service contracts. They are organized by functional portfolio (base operations, IT, professional services).",
    "MAJCOM contracting offices": "Correct. Major Command (MAJCOM) contracting offices (e.g., ACC Contracting, AMC Contracting) manage acquisitions for their respective command\\'s unique operational requirements. They are distinct from AFICC in organizational alignment.",
    "Base-level contracting squadrons": "Correct. Base contracting squadrons (e.g., 88th Contracting Squadron at Wright-Patterson AFB) handle local installation day-to-day acquisition needs \xe2\x80\x94 base support services, facilities projects, equipment \xe2\x80\x94 up to their delegated contracting authority limits.",
    "Defense Pricing and Contracting (DPC)": "Correct. DPC (formerly DPAP) is the OSD-level policy organization setting contracting policy guidance for all DoD components. DPC issues the DFARS, policy memoranda, and class deviations. It is not a contracting office but a policy authority.",
    "MAJCOM offices are exempt from public procurement posting requirements": "Incorrect. MAJCOM contracting offices must post synopsis notices on SAM.gov like all other federal contracting offices (FAR 5.203). Classified requirements have different posting rules, but the general rule requires public posting.",
    "Requirements are often operationally sensitive, classified, or OCONUS": "Correct. Command-unique requirements often involve operational sensitivity \xe2\x80\x94 which may affect the solicitation process (shorter posting periods, classified appendices), security requirements in contract clauses, and teaming considerations for contractors.",
    "MAJCOM contracts are below the SAT and don\\'t require posting": "Incorrect. MAJCOMs execute multi-million and multi-billion dollar contracts \xe2\x80\x94 far above the Simplified Acquisition Threshold. MAJCOM contracting offices are full acquisition authorities with large portfolios.",
    "MAJCOM contracting is conducted exclusively through GWACs": "Incorrect. MAJCOMs use a variety of contracting mechanisms \xe2\x80\x94 standalone competitive acquisitions, GWACs, OTAs, SAPs, and interagency agreements. MAJCOM-unique requirements often require standalone competitions.",
    "Air Combat Command (ACC)": "Correct. ACC (Air Combat Command) is a major USAF command responsible for combat air forces. ACC contracting manages requirements for aircraft maintenance, operations support, and systems unique to ACC-assigned forces.",
    "Air Mobility Command (AMC)": "Correct. AMC is responsible for global air mobility and strategic airlift. AMC contracting handles LOGCAP-type support, aerial port operations, tanker support, and mobility-related services across the AMC enterprise.",
    "Air Force Materiel Command (AFMC)": "Correct. AFMC is the science and technology, acquisition, and sustainment command. AFMC includes Air Force Research Laboratory (AFRL), Program Executive Officers, and Air Force Life Cycle Management Center (AFLCMC). The largest share of Air Force acquisition spending flows through AFMC.",
    "USAFE-AFAFRICA": "Correct. USAFE-AFAFRICA is the Air Force component of European Command and Africa Command. Its contracting offices manage OCONUS acquisitions in support of European and African theater operations, often involving host-nation agreements and Status of Forces Agreement compliance.",
    "It automatically qualifies your firm for AFICC ESS competitions": "Incorrect. No single past performance award automatically qualifies a firm for future competitions. Past performance on AFICC contracts is a strong advantage in future AFICC source selections, but each competition has its own qualification criteria.",
    "It can be leveraged as past performance across the entire AFICC enterprise in future source selections": "Correct. Past performance on one AFICC base or enterprise contract is highly relevant to future AFICC competitions. Evaluators within the AFICC enterprise share knowledge of contractor performance history, and CPARS ratings from AFICC contracts are visible across the enterprise.",
    "It exempts your firm from oral presentation requirements": "Incorrect. There is no such exemption. Each source selection team designs its own evaluation process. Oral presentations are a common evaluation tool in AFICC competitions \xe2\x80\x94 particularly for complex management approach sub-factors.",
    "It qualifies your firm for sole-source awards on all future base requirements": "Incorrect. Sole-source awards require specific statutory justification (FAR 6.302). Prior performance creates a track record but does not entitle a contractor to sole-source treatment.",

    # EVM FORMAT 1
    "WBS elements with negative CV (Cost Variance) \xe2\x80\x94 over-budget areas. Drill down to understand root cause.": "Correct. The most actionable Format 1 analysis starts with CV \xe2\x80\x94 negative CV means AC > EV, indicating a cost overrun. Sorting by CV magnitude identifies where program dollars are most at risk. Drill down to CAP (Control Account Plan) level to identify root causes: scope growth, rework, inefficiency, or inaccurate estimates.",
    "WBS elements with negative SV (Schedule Variance) \xe2\x80\x94 behind-schedule areas. Cross-check against the IMS.": "Correct. Negative SV (EV < PV) indicates the program is behind schedule in EV terms. Cross-reference Format 1 SV against the IMS to identify whether schedule slippage is on the critical path or in float-absorbing near-critical tasks.",
    "BAC vs. EAC at the total contract level \xe2\x80\x94 the delta is VAC. A growing negative VAC trend is the most critical warning sign.": "Correct. VAC (Variance at Completion) = BAC - EAC. A growing negative VAC trend \xe2\x80\x94 month over month \xe2\x80\x94 is the single most important indicator of program cost health. A program with declining CPI that does not adjust its EAC is masking the true projected overrun.",
    "MR (Management Reserve) balance \xe2\x80\x94 if MR is eroding rapidly, the contractor is using contingency to mask overruns.": "Correct. MR is budget held outside the PMB for unplanned in-scope work. Rapid MR burn-down \xe2\x80\x94 especially without corresponding PMB growth or new work authorization \xe2\x80\x94 may indicate the contractor is using MR to absorb overruns instead of properly recognizing negative variance.",
    "Undistributed Budget (UB) \xe2\x80\x94 budget not yet assigned to WBS elements. Large UB balances late in the program are a concern.": "Correct. UB represents authorized but unplanned work \xe2\x80\x94 budget not yet assigned to specific Control Accounts. Large UB balances in the middle or late phases of a program suggest poor planning, inadequate work authorization, or potential use of UB as a hidden reserve.",

    # EVM FORMAT 2-5
    "Subcontractor performance \xe2\x80\x94 if the prime\\'s work is on track but subcontractors are in trouble, supply chain management needs scrutiny": "Correct. Prime contractor CPR/IPMR data may mask subcontractor-level problems. If specific WBS elements (often subcontractor-heavy) show consistent negative variance, the prime\\'s supply chain management requires scrutiny. Government may request subcontractor-level EVM data for significant subcontracts.",
    "Compare Format 2 performance by org against staffing data \xe2\x80\x94 declining BCWP with high ACWP from a specific org often means unproductive labor": "Correct. Format 2 breaks performance data by organizational reporting elements (OREs). When an organization shows declining BCWP (accomplishment) but sustained or increasing ACWP (spending), it indicates labor investment is not translating to earned work.",
    "Baseline changes from last period \xe2\x80\x94 any retroactive replanning (moving budget backward to cover past variances) is a serious concern": "Correct. Retroactive replanning \xe2\x80\x94 changing the PMB to cover past variances \xe2\x80\x94 is prohibited without explicit government approval. Format 3 changes must always be prospective; government approval is required for significant baseline changes.",
    "Management Reserve (MR) draw-downs \xe2\x80\x94 compare total MR used against original MR balance": "Correct. Calculate the MR burn rate: at the current rate of MR usage, will the MR be exhausted before program completion? Premature MR exhaustion forces the PM into difficult tradeoffs.",
    "Budget shifts between near-term and far-term \xe2\x80\x94 \"rubber baseline\" behavior is a gaming indicator": "Correct. \\'Rubber baseline\\' behavior \xe2\x80\x94 repeatedly moving planned value (BCWS/PV) further into the future to avoid recording negative schedule variance \xe2\x80\x94 is a form of baseline gaming. This behavior must be approved through formal ECP processes.",
    "Current PMB vs. original PMB \xe2\x80\x94 large deviations indicate significant re-planning requiring government approval": "Correct. The PMB should only change through formally approved processes: Engineering Change Proposals (ECPs), Over-Target Baseline (OTB) approval, or government-approved replanning. Large deviations from the original PMB without formal authorization indicate improper baseline management.",
    "Understaffing vs. plan \xe2\x80\x94 if actual headcount is significantly below planned, BCWP will lag BCWS (negative SV). Schedule slippage is predictable.": "Correct. Format 4 provides staffing data by labor category. Comparing actual headcount to planned identifies the root cause of SV in Format 1. Understaffing is the most common and predictable schedule driver.",
    "Overstaffing vs. plan \xe2\x80\x94 more labor than planned drives ACWP above BCWP (negative CV). May indicate rework or underestimated complexity.": "Correct. Overstaffing \xe2\x80\x94 more actual labor than planned \xe2\x80\x94 drives ACWP up without corresponding BCWP gain if the additional labor is not producing incremental value. Common causes: rework from failed tests, underestimated complexity, or inefficient work authorization.",
    "LCAT mix changes \xe2\x80\x94 substituting lower-grade labor for planned senior roles may affect technical quality": "Correct. Labor category mix shifts can affect both cost and technical quality. Substituting junior staff for planned senior engineers may reduce ACWP short-term but increase rework costs and schedule risk if junior staff cannot perform at the required level.",
    "Cross-reference Format 4 with Format 1: understaffed WBS elements will show negative SV in Format 1": "Correct. This cross-format analysis is one of the most powerful tools in CPR review. If Format 4 shows understaffing in a specific organizational element, and Format 1 shows negative SV in the corresponding WBS element, the causal relationship is confirmed.",
    "Causality, not just description \xe2\x80\x94 \"labor hours exceeded plan due to test failures\" is better than \"labor hours increased\"": "Correct. The most common Format 5 weakness is descriptive narratives that describe what happened without explaining why. Government reviewers expect causal analysis: what specific event or condition caused the variance? Root cause quality is the primary criterion for Format 5 adequacy.",
    "Corrective action specificity \xe2\x80\x94 vague actions (\"team is working the issue\") with no timeline are not acceptable": "Correct. Acceptable corrective actions name a specific action, identify an owner by name and position, and include a target completion date. \\'The deputy PM is implementing a revised subcontractor surveillance plan, with monthly performance reviews beginning March 15\\' is acceptable. \\'We are working the issue\\' is not.",
    "Recovery schedule \xe2\x80\x94 if behind schedule, Format 5 should show how the contractor plans to recover": "Correct. For WBS elements with negative SV, Format 5 should include a recovery plan \xe2\x80\x94 specific actions to recover the schedule slip. If recovery is not achievable, the narrative should acknowledge that and quantify the expected schedule impact.",
    "EAC rationale \xe2\x80\x94 the Format 5 should explain the basis for the contractor\\'s EAC, especially if it differs from statistical EAC": "Correct. The contractor\\'s EAC must be explained in Format 5 when it differs materially from statistical EAC methods (BAC/CPI). If the contractor\\'s EAC is more optimistic than statistical methods predict, the government should require a detailed justification.",
    "Variance thresholds \xe2\x80\x94 ensure all threshold variances (typically CV or SV over plus or minus 10% and over $100K) have narratives": "Correct. Most government contracts specify variance thresholds (e.g., CV or SV >10% and >$100K) that require written narratives in Format 5. Inconsistency in threshold reporting is itself a compliance finding.",
    "Critical path \xe2\x80\x94 any slip on critical path tasks directly delays contract completion": "Correct. The integrated master schedule critical path is the sequence of tasks with zero total float. Any delay to a critical path task delays the program end date by the same amount. Government reviewers focus heavily on critical path health, stability, and the float status of near-critical tasks.",
    "Total Float \xe2\x80\x94 tasks with zero or negative total float are on or near critical path. Negative float means the task is already late.": "Correct. Total float represents how much a task can be delayed without delaying the program end date. Zero total float = critical path. Negative total float = the task\\'s schedule is already late relative to the plan. Negative float is a direct indicator of embedded schedule problems.",
    "Schedule density \xe2\x80\x94 unusually high milestone clusters (\"schedule packing\") are a sign of unrealistic planning": "Correct. Schedule packing \xe2\x80\x94 an unrealistic concentration of milestones or completion events in a specific period \xe2\x80\x94 suggests the schedule was built backward from a desired end date rather than built bottom-up from realistic work estimates.",
    "Logic ties \xe2\x80\x94 all tasks should have predecessor/successor relationships. Tasks with no ties cannot drive accurate critical path analysis.": "Correct. Every task in a well-structured IMS should have at least one predecessor and one successor. Tasks with no predecessor/successor relationships \xe2\x80\x94 called \\'open-ended tasks\\' or \\'dangling activities\\' \xe2\x80\x94 float freely and do not contribute to a realistic critical path analysis.",
    "Compare current IMS critical path to last period \xe2\x80\x94 an unstable critical path indicates poor schedule management": "Correct. An unstable critical path \xe2\x80\x94 one that shifts significantly month to month \xe2\x80\x94 indicates poor schedule management or deliberate baseline gaming. Major shifts suggest the schedule is being manipulated rather than updated based on actual progress.",

    # EVM INDICATORS
    "CPI < 1.0: cost overrun \xe2\x80\x94 how far, how fast is it moving?": "Correct. CPI = EV/AC. A CPI below 1.0 means the program is spending more than the budgeted value for work accomplished. The critical questions: (1) How far below 1.0? (0.95 is concerning; 0.80 is severe). (2) Is the trend worsening month over month? (3) Has it crossed the 20% completion point?",
    "VAC (negative): projected overrun at completion \xe2\x80\x94 is it growing each month?": "Correct. VAC = BAC - EAC. A growing negative VAC trend \xe2\x80\x94 month over month \xe2\x80\x94 is the most critical program cost health indicator. If VAC deteriorates by $5M each month report, the program office needs to act before the overrun becomes unmanageable.",
    "SPI < 1.0: behind schedule \xe2\x80\x94 note which months it started declining": "Correct. SPI = EV/PV. SPI < 1.0 indicates schedule slippage in EV terms. Identifying when SPI started declining is critical \xe2\x80\x94 was it a specific event (test failure, key personnel departure) or a slow degradation?",
    "Red flag: CPI trending down 3+ months in a row = systemic problem, not a blip": "Correct. Three consecutive months of declining CPI is the strongest indicator of a systemic program problem. Research by DAU and Paul Solomon shows that after three months of declining CPI, the trend almost never reverses significantly. At this point, EAC = BAC/CPI is the most reliable predictor.",
    "Sort CV column: the largest negative CV numbers are your biggest overruns in dollars": "Correct. Sorting by CV magnitude identifies the WBS elements consuming the most excess cost. Cross-reference against element size (BAC) \xe2\x80\x94 a -$5M CV on a $10M element (50% overrun) is more alarming than a -$5M CV on a $100M element.",
    "Sort SV column: the largest negative SV numbers are your most schedule-critical slips": "Correct. After CV, sort SV to identify which WBS elements are furthest behind schedule. Cross-reference against the IMS to determine whether these elements are on the critical path.",
    "Note if the same WBS element appears in both CV and SV worst lists \xe2\x80\x94 that is a compounding problem": "Correct. A WBS element appearing in both the worst CV and worst SV lists is a compounding problem: spending more than planned AND achieving less than planned simultaneously. These dual-variance elements pose the highest program risk.",
    "Compare to last month: are the same elements getting worse, or are new ones appearing?": "Correct. Trend analysis is more informative than single-period snapshots. The same elements getting progressively worse indicates an uncorrected systemic problem. New elements appearing suggests scope growth or new technical challenges \xe2\x80\x94 a broader problem.",
    "Cross-check against Format 5: do these elements have variance narratives? If not, ask why.": "Correct. Every WBS element exceeding variance thresholds must have a Format 5 narrative. If high-variance elements lack narratives, it indicates either inadequate EVM reporting compliance or the contractor does not understand the significance of the variance.",
    "Does the root cause actually explain the CV/SV? Vague causes (\"resource constraints\") are a red flag.": "Correct. \\'Resource constraints\\' is the most commonly used vague root cause in Format 5 \xe2\x80\x94 it explains nothing specific. What resources? What constraint? Why was it not anticipated? Government reviewers should push back on vague narratives.",
    "Is there a specific, measurable corrective action with a named owner and due date?": "Correct. Corrective actions must be SMART: Specific, Measurable, Assigned (who is responsible), Realistic, and Time-bound (by when). Corrective actions without owners and due dates are aspirational \xe2\x80\x94 not commitments.",
    "Does the corrective action realistically address the root cause?": "Correct. A common trap is well-written corrective actions that do not address the identified root cause. If the root cause is \\'test failures due to software integration problems,\\' a corrective action of \\'increase staffing\\' may not solve the underlying software issue.",
    "Mismatch check: does the narrative address the same WBS elements with the biggest variances in Format 1? Inconsistency = narratives written independently of the data.": "Correct. A frequent quality issue: Format 5 narratives addressing WBS elements with minor variance while high-variance elements go unexplained. This indicates the narratives were written independently without cross-referencing Format 1 data.",
    "Track last month\\'s corrective actions: did they produce improvement? If CPI did not move, the action was ineffective.": "Correct. Corrective action effectiveness tracking is the most important longitudinal review skill. If the PM committed to a specific corrective action last month, did CPI/SPI improve for that WBS element this month? Repeated commitments with no measurable improvement indicate the actions are ineffective.",
    "Any new entries since last month? All changes require CO approval via formal contract modification.": "Correct. Format 3 documents all changes to the PMB. Any significant change requires government approval. Reviewing Format 3 for unauthorized changes \xe2\x80\x94 new entries without corresponding contract modifications \xe2\x80\x94 is an important compliance check.",
    "Budget transfers between WBS elements: legitimate re-planning or hiding overruns in other accounts?": "Correct. Internal replanning can be used legitimately to reflect refined work planning. However, it can also be used to spread overruns across multiple elements to keep individual elements below reporting thresholds. Large unexplained budget transfers should trigger questions.",
    "Management Reserve (MR) draws: how much MR remains? MR burn rate is a key program health indicator.": "Correct. Calculate the MR burn rate: (Original MR - Current MR Balance) / Months elapsed = Average MR burn per month. If MR will be exhausted significantly before contract completion, the program faces difficult choices.",
    "Undistributed Budget (UB): large UB that\\'s been sitting means work is not yet planned in detail \xe2\x80\x94 schedule risk.": "Correct. UB represents authorized work not yet planned at the Control Account level. Large, persistent UB late in a program indicates work is not being planned in detail \xe2\x80\x94 which means schedule cannot be tracked, and the PMB understates the full scope of planned activity.",

    # STAFFING ANALYSIS
    "Cross-reference: which WBS elements have negative SV in Format 1? Are those same elements fully staffed in Format 4?": "Correct. This cross-format analysis confirms staffing causality. If Format 1 shows negative SV on Element X, and Format 4 shows Element X is staffed at 60% of plan, the causal relationship is clear.",
    "Understaffed + negative SV = schedule slip will continue regardless of recovery commitments": "Correct. If a WBS element is significantly understaffed AND showing negative SV, no amount of \\'working the issue\\' will recover the schedule until staffing reaches plan levels. Recovery is mathematically impossible without additional resources.",
    "Check key personnel: are the named experts from the proposal actually on the program?": "Correct. Key personnel commitments made in the winning proposal are often contractually binding. If the proposal named a specific PM or Deputy PM, and that person is not on the program, the contractor may be in breach of contract.",
    "Headcount trending down while schedule is behind = problem getting worse, not better": "Correct. A declining headcount trend combined with negative SV is a strongly negative leading indicator. It means the contractor is not just behind \xe2\x80\x94 they are further reducing the resources needed to recover.",

    # IMS ANALYSIS
    "Has the critical path changed since last month? New tasks appearing on the critical path = scope risk emerging": "Correct. Critical path stability is a key schedule health indicator. New tasks appearing on the critical path indicate either previously float-rich tasks have consumed their float, or the contractor is manipulating the schedule.",
    "Total float on near-critical tasks: anything under 10 days of float is effectively critical": "Correct. Tasks with very low total float (10 days or fewer) are operationally critical \xe2\x80\x94 any minor disruption will push them onto the critical path. Monitoring near-critical float consumption is an early warning system for emerging critical path issues.",
    "Are key milestones (CDR, PDR, IOT&E) still tracking to the APB schedule?": "Correct. Key program milestones \xe2\x80\x94 CDR, PDR, IOT&E \xe2\x80\x94 are anchored in the APB and are the primary schedule commitments to oversight stakeholders. Slipping these milestones triggers APB reporting and potential Nunn-McCurdy concerns.",
    "Negative total float (tasks already late): how many, and are they on the path to a contract milestone?": "Correct. Negative total float is an unambiguous indicator of existing schedule problems embedded in the baseline. If negatively-floated tasks feed into a contract milestone, that milestone is de facto late.",
    "Compare to Format 5: are schedule slips on the critical path explained in the variance narratives?": "Correct. Critical path schedule slippage must be addressed in Format 5 narratives. If the IMS shows critical path tasks with negative SV and Format 5 narratives for those WBS elements are missing or vague, this is a significant compliance gap.",

    # PROPOSAL INSTRUCTIONS
    "\"Volume I \xe2\x80\x94 Technical Approach, not to exceed 50 pages, 12pt Times New Roman, 1-inch margins\"": "Correct. Volume I contains the technical approach \xe2\x80\x94 typically the highest-weighted evaluation factor. Page limits are strictly enforced; a non-compliant submission may be deemed non-responsive. Every page should directly support a strength evaluation against Section M criteria.",
    "\"Volume II \xe2\x80\x94 Management Approach, not to exceed 25 pages\"": "Correct. The Management Volume demonstrates the contractor\\'s ability to organize, staff, and execute. Key elements: organizational chart, key personnel resumes, program management methodology, risk management approach, quality assurance plan, and subcontractor management strategy.",
    "\"Volume III \xe2\x80\x94 Past Performance, provide up to 3 references using the government-provided form\"": "Correct. Past performance is evaluated using CPARS data and submitted references. Select references that are: (1) recent (within 3-5 years), (2) relevant (similar scope, complexity, contract type), and (3) had excellent CPARS ratings.",
    "\"Volume IV \xe2\x80\x94 Price/Cost, no page limit, must include completed DD Form 1423 (CDRLs)\"": "Correct. The Price/Cost Volume must be complete, consistent with the technical approach, and independently auditable. Key elements: labor category hours by WBS, basis of estimate, direct labor rates, indirect rates, other direct costs, and required forms.",
    "\"All volumes must be submitted via SAM.gov by 4:00 PM EST on [date]\"": "Correct. Proposal submission requirements are strictly enforced. Late proposals are typically rejected. SAM.gov submission requires advance registration and testing \xe2\x80\x94 submit a day early to allow for technical issues. Time zone matters \xe2\x80\x94 EST vs. EDT can cause a missed deadline.",
    "Section L says: \"Describe your staffing plan.\" Section M says staffing is NOT an evaluation factor. Your staffing section will be read for compliance only, not scored. Keep it short.": "Correct. Section M defines what wins points; Section L defines what is required for compliance. When Section M does not list staffing as a factor, the staffing section is a pass-fail compliance element \xe2\x80\x94 not scored. Extensive page count on non-scored sections wastes limited page count.",
    "Section L says: \"Describe your technical approach.\" Section M has three sub-factors: Innovation (15%), Risk Mitigation (25%), Schedule Realism (20%). Your technical approach must address each sub-factor with sub-headers that mirror M language.": "Correct. Structure the technical volume around Section M\\'s evaluation sub-factors. Use the exact M language as sub-headers \xe2\x80\x94 evaluators are scored against Section M, so they need to find information quickly. Innovation, Risk Mitigation, and Schedule Realism each need dedicated sections with evidence and discriminators.",
    "Winning proposals use M as the writing guide and L as the compliance checklist.": "Correct. This is the master principle of proposal writing. Section M defines what evaluators score. Section L defines what must be included for compliance. Write to Section M. Check against Section L. Never reverse this.",
    "A Strength must EXCEED the requirement. \"We will provide monthly status reports\" meets a requirement. \"We will provide a real-time dashboard with threshold alerts 48 hours before a schedule variance becomes actionable\" earns a Strength.": "Correct. SSEB members are looking for strengths \xe2\x80\x94 features that exceed requirements and provide measurable benefit. Meeting requirements earns \\'Acceptable\\' \xe2\x80\x94 not a strength. Every discriminating element should clearly exceed the stated requirement in a specific, verifiable way.",
    "Strengths must be documented \xe2\x80\x94 evaluators can only credit what they can see and quote.": "Correct. Source selection decisions are legally defensible only when based on documented evaluation. If an SSEB member believes a proposal feature is a strength but cannot quote specific text, the strength cannot be formally recorded.",
    "Use the Government exact M language as section headers.": "Correct. Using Section M language as proposal headers makes evaluators\\' jobs easier \xe2\x80\x94 they can immediately locate information relevant to their scored sub-factor. It also reduces the risk that evaluators miss a strength because they could not find the relevant section.",
    "Each sub-factor needs at least one discriminating element your competitors cannot match.": "Correct. Discriminators are the strategic heart of proposal writing \xe2\x80\x94 a feature or capability only your team can credibly offer. Proposals without discriminators earn \\'Acceptable\\' across the board, which loses to a proposal with even one genuine strength.",

    # SOURCE SELECTION PROCESS
    "Appoint the SSEB Chair and SSAC Chair": "Correct. The Source Selection Authority (SSA) appoints the SSEB and SSAC Chairs before the solicitation is released. This ensures the evaluation structure is in place and all members understand their roles before proposals arrive.",
    "Approve the Source Selection Plan before solicitation release": "Correct. The Source Selection Plan (SSP) defines how proposals will be evaluated \xe2\x80\x94 rating scales, factor weights, evaluation methodologies. The SSA must approve the SSP before the RFP is released to ensure Section M is aligned with the SSP.",
    "Review the SSAC recommendation (may accept, reject, or modify)": "Correct. The SSAC provides the SSA with a written best-value tradeoff recommendation. The SSA reviews but is not bound by it \xe2\x80\x94 the SSA may accept, reject, or modify the recommendation based on independent judgment. Rationale for any deviation must be documented.",
    "Sign the Source Selection Decision Document (SSDD)": "Correct. The SSDD is the SSA\\'s written, legally defensible decision document explaining the best-value determination. It must be sufficiently detailed to withstand a GAO protest \xe2\x80\x94 explaining how the technical advantages of the selected offeror justified any price premium.",
    "The SSDD is the legal basis for the award \xe2\x80\x94 it must be defensible in a protest": "Correct. The SSDD is the most legally significant acquisition document. In a GAO protest, the GAO reviews the SSDD to determine whether the source selection was reasonable, consistent with stated criteria, and documented. SSDD deficiencies are the most common grounds for sustained protests.",

    # PRE-SOLICITATION
    "Market Research: RFI releases, industry days, one-on-one meetings (within procurement integrity rules)": "Correct. Market research (FAR 10) must precede any acquisition. Methods include: Requests for Information (RFIs), sources sought notices, industry days, and one-on-one meetings. The goal is to understand the marketplace, identify potential offerors, and inform acquisition strategy.",
    "Acquisition Strategy: Contract type, competition approach, sole source justification (if any)": "Correct. The Acquisition Strategy defines: contract type (FFP, CPIF, T&M), competition approach (full and open, set-aside, sole source), source selection process (best value, LPTA), and acquisition milestones.",
    "Source Selection Plan (SSP): SSA approves the SSP \xe2\x80\x94 defines factors, sub-factors, weights, rating scales, and the evaluation process BEFORE solicitation release": "Correct. The SSP is the government\\'s internal roadmap for the evaluation. It must be approved before the RFP is released because Section M must be consistent with the SSP. The SSP is not released to offerors.",
    "Draft RFP (DRFP): Government may release a DRFP for industry comment before the final RFP": "Correct. A Draft RFP is optional but common for complex acquisitions. Industry comments help the government identify ambiguous requirements, unreasonable restrictions, and compliance burden before finalizing. DRFP comment periods are typically 30-60 days.",
    "Synopsis: Required FAR 5.203 notice on SAM.gov at least 15 days before solicitation release": "Correct. FAR 5.203 requires a synopsis notice on SAM.gov at least 15 days before issuing the solicitation (for acquisitions over $25K). The synopsis gives industry advance notice, allowing small businesses to identify teaming partners before the RFP drops.",
    "RFP Release: Full solicitation posted to SAM.gov. Sections L, M, C, H, I, J all released simultaneously": "Correct. The final RFP is posted to SAM.gov with all attachments. Section C (SOW), Section H (special requirements), Section I (contract clauses), Section J (attachments), Section L (instructions), and Section M (evaluation factors) are all released at the same time.",
    "Pre-Proposal Conference: Government may hold a conference to answer questions (not always conducted)": "Correct. A pre-proposal conference is optional but common for complex acquisitions. Questions and answers from the conference must be formally documented and issued to ALL offerors via amendment \xe2\x80\x94 no proprietary answers.",
    "Q&A Period: Written questions answered via amendment distributed to ALL offerors \xe2\x80\x94 no private answers": "Correct. Procurement integrity requirements (FAR 3.1) prohibit private communications giving any offeror an advantage. All questions are answered via amendment distributed simultaneously. Answers received privately create protest risk.",
    "Amendments: Any change to the RFP requires a formal amendment. Significant amendments may extend the due date": "Correct. Any change to the RFP requires a formal amendment posted to SAM.gov. Major changes affecting the technical approach or giving offerors insufficient time to respond must be accompanied by a due date extension. Failure to extend for significant amendments is protest grounds.",
    "Industry is prohibited from contacting SSEB members during this period (procurement integrity)": "Correct. After the solicitation closes, the source selection is in \\'blackout\\' \xe2\x80\x94 industry contact with SSEB members is prohibited under procurement integrity rules (FAR 3.1 and the Procurement Integrity Act). Marketing calls or informal conversations that could influence the evaluation may constitute a procurement integrity violation.",
    "Initial Proposal Evaluation: SSEB teams evaluate each volume, document Strengths/Weaknesses/Deficiencies": "Correct. SSEB panels (typically separate panels for Technical, Management, and Past Performance) evaluate proposals against Section M criteria. Each evaluator documents Strengths (exceeds requirements), Weaknesses (needs attention), Significant Weaknesses (performance risk), and Deficiencies (fails a mandatory requirement).",
    "Competitive Range Determination: CO may exclude proposals with no realistic chance of award (FAR 15.306)": "Correct. After initial evaluation, the CO may establish a competitive range \xe2\x80\x94 excluding proposals that are technically unacceptable or so weak they have no realistic chance of award after discussions. Excluded offerors must be notified and may request a pre-award debrief.",
    "Notice to Excluded Offerors: Eliminated offerors notified and may request a pre-award debrief": "Correct. FAR 15.505 requires notification to offerors excluded from the competitive range. Excluded offerors may request a pre-award debrief within 3 days \xe2\x80\x94 the government must provide specific information about strengths, weaknesses, and deficiencies within 5 days.",
    "Price/Cost Analysis: Price reasonableness and cost realism review (for cost-type contracts)": "Correct. For fixed-price contracts, the CO performs price reasonableness analysis. For cost-type contracts, the CO also performs cost realism analysis \xe2\x80\x94 an unrealistically low cost proposal on a cost-type contract may indicate technical misunderstanding.",
    "SSAC Recommendation: SSAC provides written best-value tradeoff recommendation to SSA": "Correct. The SSAC \xe2\x80\x94 typically a panel of senior government officials \xe2\x80\x94 reviews the SSEB\\'s individual ratings and conducts a tradeoff analysis: is the higher-rated offeror\\'s technical advantage worth the price premium? The SSAC documents its reasoning in a recommendation to the SSA.",
    "Source Selection Decision Document (SSDD): SSA signs, documenting independent best-value rationale": "Correct. The SSDD is the SSA\\'s independent best-value determination. It must articulate: (1) comparative strengths, weaknesses, and deficiencies of competing offerors; (2) the price/technical tradeoff rationale; and (3) the basis for selecting the awardee as best value.",
    "Contract Execution: CO executes \xe2\x80\x94 award notice posted to SAM.gov": "Correct. The CO executes the contract and the award notice is posted to SAM.gov per FAR 5.301. The contract is legally binding upon the CO\\'s signature on behalf of the government and the contractor\\'s signature.",
    "Unsuccessful Offeror Notifications: Required within 3 days of award (FAR 15.503)": "Correct. FAR 15.503 requires postaward notifications to unsuccessful offerors within 3 days of award. This triggers the 3-day window for requesting a debrief and the 10-day window for filing a GAO protest.",
    "Debriefs (FAR 15.506): Mandatory if requested within 3 days of notification. Government must reveal your ratings, strengths/weaknesses, and award rationale.": "Correct. FAR 15.506 entitles unsuccessful offerors to a debrief. The government must provide: the offeror\\'s technical ratings by factor, the overall ranking if applicable, the rationale for award, and identify specific weaknesses or deficiencies in the proposal.",
    "GAO Protests: Unsuccessful offerors may protest to GAO within 10 days of debrief. CO issues a stay of performance pending outcome.": "Correct. Under the Competition in Contracting Act, an unsuccessful offeror may protest to GAO within 10 days of a required debrief. A timely protest triggers an automatic stay of contract performance. GAO typically resolves protests within 100 days.",

    # BD
    "Strong BD performance \xe2\x80\x94 a large pipeline maximizes win probability": "Incorrect. A large pipeline without qualification exhausts proposal resources on low-probability pursuits. A $500M pipeline with 15% average pWin is less productive than a $200M pipeline with 40% average pWin. Quality beats volume in BD pipeline management.",
    "An undisciplined pipeline strategy that is likely wasting proposal resources on low-probability pursuits": "Correct. A large pipeline with low average pWin indicates poor opportunity qualification. Every proposal costs money (people, time, B&P budget). Low-pWin proposals are expensive distractions from high-probability pursuits.",
    "The contractor should increase proposal volume to improve win totals": "Incorrect. Increasing proposal volume without improving win rate just increases B&P spending. The solution is better pipeline discipline \xe2\x80\x94 improving the quality of pursuits (higher pWin) rather than increasing quantity.",
    "Normal BD operations \xe2\x80\x94 most opportunities in any pipeline have low pWin": "Correct. Most early-stage opportunities have inherently low pWin because they are being tracked before the company has built a discriminating solution. As opportunities mature through the BD lifecycle (identify \xe2\x86\x92 qualify \xe2\x86\x92 shape \xe2\x86\x92 pursue), pWin should increase.",

    # COR AUTHORITY
    "The COR has authority to award contract modifications over $150,000": "Incorrect. CORs have NO contracting authority \xe2\x80\x94 they cannot award, modify, or terminate contracts under any circumstances. Only the Contracting Officer (with a warrant) can award modifications. A COR who attempts to commit the government creates an unauthorized commitment.",
    "The COR is the primary author of CPARS ratings and the most influential voice in recompete positioning": "Correct. CPARS ratings are the government\\'s official record of contractor past performance. The COR typically drafts the CPARS assessment \xe2\x80\x94 making the COR the most influential person in determining a contractor\\'s past performance record, a primary evaluation factor in future competitions.",
    "The COR controls the government\\'s budget allocation for the contract": "Incorrect. The COR does not control budgets. Budget allocation is the responsibility of the program Resource Manager (or Comptroller), the PM, and the financial management chain.",
    "The COR approves all invoices before the CO processes payment": "Partially correct. The COR certifies that work was performed (technical verification) before the CO approves payment. The chain is: COR certifies \xe2\x86\x92 CO approves \xe2\x86\x92 Finance pays. The COR\\'s role is technical certification, not the final financial approval.",

    # PWS RESPONSE
    "Provide a detailed task-by-task breakdown with labor hours per activity": "Correct. A strong technical approach responds directly to each PWS task with a detailed execution narrative \xe2\x80\x94 including labor hours by task, specific tools and methodologies, and measurable outcomes.",
    "Describe the management framework, quality metrics, and how outcomes will be measured and achieved": "Correct. The management approach section should explain the governance structure, performance metrics, quality control processes, and how the contractor will demonstrate value throughout performance.",
    "Mirror the PWS structure with a direct response to each performance standard": "Correct. Using the PWS structure as the proposal organization framework \xe2\x80\x94 with section headers mirroring PWS section numbers \xe2\x80\x94 allows evaluators to quickly verify compliance with every performance standard.",
    "Propose a fixed schedule of deliverables aligned to the government\\'s task list": "Correct. A clear deliverables matrix \xe2\x80\x94 showing each PWS-required deliverable, the delivery date, the responsible person, and the acceptance criteria \xe2\x80\x94 demonstrates planning rigor and gives the government a ready-made performance baseline.",

    # COST-TYPE COMPLIANCE
    "Monthly financial reporting to the contracting officer": "Correct. Cost-type contracts require regular financial reporting \xe2\x80\x94 typically monthly invoices with actual cost detail. The CO and COR monitor these reports to ensure costs are being allocated correctly and performance is tracking to plan.",
    "Contemporaneous timekeeping \xe2\x80\x94 capturing time by contract daily, not retroactively": "Correct. DCAA requires employees on cost-type contracts to capture time contemporaneously \xe2\x80\x94 at the time of performance, not reconstructed after the fact. Retroactive timesheet entries are a serious accounting system deficiency.",
    "Written compensation policies approved by the CO before award": "Incorrect as described. Compensation policies are part of the contractor\\'s business system, not individually CO-approved per contract. Compensation must be \\'reasonable\\' under FAR 31.205-6, but individual CO pre-approval of compensation policies is not a standard requirement.",
    "Independent audit of indirect rates by a certified public accountant": "Incorrect for most cost-type contracts. DCAA \xe2\x80\x94 a government audit organization \xe2\x80\x94 not a commercial CPA firm, performs the required audits on cost-type government contracts. However, companies without government audit history may use commercial auditors for incurred cost submissions until DCAA establishes audit jurisdiction.",

    # RECOMPETE TIMING
    "12 months before contract expiration, when the RFP timeline becomes clear": "Correct. This is typically when the incumbent begins intensive recompete positioning \xe2\x80\x94 the window when the government\\'s acquisition timeline becomes visible through pre-solicitation notices and RFI releases. At 12 months, the contractor should have a preliminary proposal team and an active intelligence-gathering operation.",
    "6 months before expiration, when the government issues a pre-solicitation notice": "Correct. The pre-solicitation notice typically drops 6-12 months before the RFP. At this point, all potential competitors know the timeline, teaming conversations intensify, and the incumbent\\'s positioning should be fully formed.",
    "At contract award \xe2\x80\x94 the moment the current period of performance begins": "Correct. Sophisticated contractors begin recompete strategy at contract award \xe2\x80\x94 sometimes called \\'Day 1 positioning.\\' The first day of performance sets the trajectory for CPARS ratings, customer relationships, and technical differentiation that will ultimately determine the recompete outcome.",
    "30 days before proposal submission deadline": "Incorrect. Beginning recompete work 30 days before proposal submission is far too late. By this point, the proposal team should be in full production on a completed draft. 30 days out is proposal writing time, not strategy time.",

    # DAWIA
    "Apply directly for GS-14 Program Manager positions": "Incorrect. Entry into DoD acquisition careers typically starts at GS-7 through GS-12 levels. GS-14 PM positions typically require 10+ years of acquisition experience and DAWIA Level III (or APWG equivalent) certification.",
    "Get 10 years of private sector experience first": "Incorrect. Private sector experience is valuable but not a prerequisite. Many acquisition professionals begin directly from college, military service, or other government positions.",
    "Paid courses costing $2,000-5,000 per course": "Incorrect. DAU (Defense Acquisition University) courses are provided at no cost to the DoD acquisition workforce \xe2\x80\x94 funded by DoD as a workforce development investment.",
    "Free to DoD acquisition workforce members and mandatory for certification": "Correct. DAU courses are free to DoD acquisition workforce members (civilians and military) and required for DAWIA certification. DAU offers courses in-person at Fort Belvoir, VA and online. Key courses include ACQ 101, ACQ 202, CON 200, and PM certifications.",
    "Only available to military officers": "Incorrect. DAU courses are available to all DoD acquisition workforce members \xe2\x80\x94 military officers, enlisted personnel, and civilian employees. Many critical acquisition positions are held by civil servants.",

    # RISK MANAGEMENT
    "Cover known, well-defined work that is already planned": "Incorrect. This describes the Performance Measurement Baseline (PMB). Management Reserve (MR) is budget held outside the PMB for unplanned in-scope work \xe2\x80\x94 specifically for risks and unforeseen events, not for planned work.",
    "Fund identified risks and unforeseen events that affect the Performance Measurement Baseline": "Correct. MR is held by the PM above the PMB for unplanned, in-scope events. When an identified risk materializes, the PM can draw from MR to fund the additional work \xe2\x80\x94 after the MR draw is formally documented and approved.",
    "Pay for program management overhead costs": "Incorrect. Program management overhead is included within the PMB. MR is specifically for unplanned events, not for covering routine management costs.",
    "Tracking the number of risks added per month": "Incorrect. Tracking the raw number of risks added per month is a process metric, not an indicator of risk management effectiveness. Meaningful risk tracking focuses on risk probability, impact, and mitigation progress.",
    "Showing how risk probability and impact decrease over time as mitigation actions are executed": "Correct. Effective risk tracking demonstrates that the risk management process is actually reducing risk. The risk burn-down chart (number and severity of open risks over time) is the most powerful visualization of risk management effectiveness.",
    "Charting contractor cost overruns by risk category": "Incorrect. Charting actual cost overruns by risk category is a post-mortem activity. Proactive risk management tracks risks before they materialize \xe2\x80\x94 monitoring leading indicators and verifying that mitigation actions are being executed on schedule.",
    "A potential future adverse event that has not yet occurred": "Correct. This is the definition of a risk. Risk management distinguishes between risks (potential future events that may or may not occur) and issues (events that have already occurred). Risks have probability and impact assessments.",
    "A risk that has already materialized and requires a corrective action plan": "Correct. When a risk materializes, it becomes an issue. The risk register entry transitions to the issue log. The response shifts from mitigation (preventing occurrence) to corrective action (managing the impact).",
    "Any unplanned cost or schedule variance": "Incorrect. Not all variances are risks. A variance is a measurement of actual performance against plan. A risk is a potential future adverse event. However, variances can indicate risk materialization or be early warning indicators of emerging risks.",
    "Budget that has been allocated but not yet spent": "Incorrect. \\'Budget allocated but not spent\\' describes BCWS vs. ACWP \xe2\x80\x94 an EVM concept. Neither BCWS nor the difference between BCWS and ACWP is the definition of a risk.",
    "Budget that has not yet been assigned to specific control accounts or work packages": "Correct for Undistributed Budget (UB). UB represents authorized program budget not yet distributed to specific WBS elements. In EVM, UB appears in Format 3 (Baseline) and should decrease as the program matures.",

    # OPPORTUNITY MANAGEMENT
    "Identifying a new contract vehicle that reduces administrative costs": "Incorrect for risk response context. Identifying a new contract vehicle is an opportunity response \xe2\x80\x94 exploiting an opportunity. Vehicle selection is a pre-award acquisition strategy decision.",
    "Exploiting early technology maturation to reduce schedule by accelerating testing": "Correct. This is a classic opportunity response \xe2\x80\x94 when technology matures faster than expected, the PM can exploit that maturation to accelerate the test program and potentially reduce schedule. Opportunity management proactively exploits favorable program conditions.",
    "Hiring additional staff to address a schedule delay": "Incorrect for risk response. Hiring additional staff to address an existing schedule delay is an issue response (corrective action) \xe2\x80\x94 not a risk response. Risk responses are planned before the event occurs.",

    # CPI
    "The program will likely recover to a CPI > 0.90 by completion": "Incorrect. Empirical research (Christensen, 1999; Solomon, 2014) consistently shows that CPI rarely improves significantly after the 20% completion point. A program at 20%+ completion with CPI = 0.80 is statistically unlikely to recover above 0.85 at completion.",
    "This is too early to draw meaningful conclusions about final CPI": "Incorrect for programs past 20% completion. Research shows that after 20% completion, CPI stabilizes and the EAC = BAC/CPI formula becomes highly predictive (within \xb110% of final cost 70% of the time). \\'Too early\\' applies only at very low percent completion.",
    "The CPI is unlikely to recover significantly; a substantial cost overrun at completion is probable": "Correct. This is the empirically supported conclusion for a program past 20% completion with declining CPI. The PM must: (1) recalculate EAC using BAC/CPI, (2) validate with bottoms-up analysis, (3) brief the PEO/SAE on the revised estimate, and (4) develop a corrective action plan.",

    # RISK PROCESS STEPS
    "Plan, Identify, Analyze, Track, Control": "Correct. The DoD Risk Management process follows this five-step cycle: (1) Plan \xe2\x80\x94 establish the risk management approach; (2) Identify \xe2\x80\x94 systematically find potential risks; (3) Analyze \xe2\x80\x94 assess probability and impact; (4) Track \xe2\x80\x94 monitor risk indicators and mitigation progress; (5) Control \xe2\x80\x94 implement mitigation actions and update the risk register.",
    "Identify, Analyze, Plan, Track, Control": "Incorrect. The DoD framework begins with Plan (establishing the approach before identifying risks). The correct sequence is Plan \xe2\x86\x92 Identify \xe2\x86\x92 Analyze \xe2\x86\x92 Track \xe2\x86\x92 Control. Starting with Identify before establishing a risk management plan leads to inconsistent, unstructured risk identification.",
    "Analyze, Identify, Mitigate, Retire, Report": "Incorrect. This is not the standard DoD Risk Management framework. \\'Retire\\' is not a distinct phase in the DoD 5-step process. The correct sequence is Plan \xe2\x86\x92 Identify \xe2\x86\x92 Analyze \xe2\x86\x92 Track \xe2\x86\x92 Control.",

    # MR
    "MR is never included \xe2\x80\x94 it violates the Anti-Deficiency Act": "Incorrect. Management Reserve is a standard and required element of EVM-based program management. MR is held above the PMB but within the total program budget \xe2\x80\x94 it does not violate the Anti-Deficiency Act.",
    "MR is included above the Performance Measurement Baseline to cover risk events": "Correct. MR sits above the PMB in the total program budget hierarchy: MR + PMB = Contract Budget Base (CBB). MR is available to the PM for unplanned, in-scope work \xe2\x80\x94 drawn down via formal MR authorization and documented in CPR Format 3.",
    "MR is held by the contracting officer and cannot be accessed by the PM": "Incorrect. MR is held by the PM (or program office) \xe2\x80\x94 not the contracting officer. The PM controls MR usage within the bounds of the contract\\'s EVM provisions.",

    # DESIGN REVIEWS
    "Validate that system requirements are complete at the beginning of Engineering & Manufacturing Development": "Incorrect for PDR/CDR context. This describes the Systems Requirements Review (SRR) objective. PDR confirms the preliminary design meets requirements; CDR confirms the detailed design is stable enough to proceed to production.",
    "Confirm the detailed design is sufficiently mature to proceed with production": "Correct for CDR. The Critical Design Review (CDR) is held late in Engineering & Manufacturing Development. Its purpose is to confirm: (1) the detailed design is complete and meets all requirements; (2) manufacturing processes are defined; (3) the design is stable enough to proceed to LRIP.",

    # PEO
    "Signs all contracts on behalf of the government": "Incorrect as a description of the PEO. The PEO is a senior acquisition official providing oversight of a portfolio of programs \xe2\x80\x94 not a contracting authority. Contract signing authority rests with the Contracting Officer.",
    "Manages a portfolio of programs and is the direct superior of individual Program Managers": "Correct. The PEO manages a portfolio of related acquisition programs, with individual PMs reporting to the PEO. Examples: PEO Aviation (Army), PEO Ships (Navy), PEO C2 (Air Force). The PEO is accountable to the SAE for portfolio health.",
    "Reports directly to the Secretary of Defense": "Incorrect for PEO. PEOs report to the Service Acquisition Executive (SAE) \xe2\x80\x94 who reports to the Service Secretary, not directly to SECDEF.",
    "A congressional oversight committee for major programs": "Incorrect. Congressional oversight committees (SASC, HASC, SAC-D, HAC-D) provide legislative oversight but are not program management organizations. They do not approve milestone decisions.",
    "A cross-functional team of government and contractor representatives responsible for a specific program area": "Incorrect for PEO. This describes an Integrated Product Team (IPT). The PEO is an individual senior official with a portfolio of programs.",
    "An OSD-level board that approves milestone decisions": "Incorrect for PEO. The Defense Acquisition Board (DAB) is the OSD-level body that reviews major milestone decisions for ACAT I programs. The PEO is a service-level official.",

    # CAPE
    "OSD Cost Assessment and Program Evaluation (CAPE)": "Correct. CAPE is the OSD office responsible for independent cost estimates, program assessments, and analytical support to USD(A&S) and SECDEF. CAPE produces Independent Cost Estimates (ICEs) for ACAT I programs at milestone reviews.",
    "Congressional defense committees": "Correct. SASC, HASC, SAC-D, and HAC-D provide legislative oversight. They authorize programs through the NDAA and fund them through appropriations. Congressional concerns can delay milestones, reduce funding, or mandate program restructuring.",
    "Combatant Commands and operational users through JCIDS": "Correct. The warfighter need originates with Combatant Commands and operational users. Through the JCIDS process, operational users document capability gaps, which drive requirements documents (ICD, CDD, CPD).",

    # COMMUNICATION
    "Limit briefings to 1 slide, 3 bullets, and 5 minutes of Q&A": "Incorrect for executive acquisition communications. This is an extreme oversimplification. Executive acquisition briefings have specific content requirements \xe2\x80\x94 APB status, CPI/SPI trends, major risks, and upcoming decisions.",
    "Structure communications as 1 core message, 3 supporting data points, and 5-minute verbal summary": "Correct. This is a practical executive communication framework for program office briefings. Lead with the single most important message, support it with three data points, and be prepared to deliver the summary in 5 minutes or less.",
    "Set 1-year, 3-year, and 5-year program objectives for executives": "Incorrect for briefing structure. Setting long-range objectives is a program planning function, not an executive briefing communication structure.",

    # MILESTONES (timing)
    "After Milestone C, before production begins": "Incorrect. Milestone B occurs before Milestone C. Milestone B authorizes entry into EMD \xe2\x80\x94 long before Milestone C (which authorizes production).",
    "Before Milestone A, during the Materiel Solution Analysis phase": "Correct for the ICD. The Initial Capabilities Document is validated before Milestone A as an input to the MSA phase. The ICD establishes the capability gap and potential approaches, informing the AoA and Milestone A decision.",
    "During the Technology Maturation and Risk Reduction phase (Phase A)": "Correct for the CDD. The CDD is typically drafted and validated during the TMRR phase \xe2\x80\x94 after Milestone A and before Milestone B. The CDD defines the detailed system requirements (KPPs, KSAs, APAs).",

    # CONGRESS
    "They can directly cancel programs through committee votes at any time": "Incorrect. Congress cannot cancel individual programs through simple committee votes \xe2\x80\x94 it must act through legislation (authorization or appropriations). Program termination requires legal action, not informal committee action.",
    "They influence authorization and appropriations legislation, and their concerns can affect program funding and direction": "Correct. Congress exercises acquisition oversight through: (1) the NDAA (authorization) \xe2\x80\x94 establishing program authorities and setting acquisition policy; and (2) appropriations acts \xe2\x80\x94 actually funding programs. Congressional concerns can lead PEOs and PMs to restructure programs proactively.",
    "They must approve all contracts over $100M": "Incorrect. Congress does not approve individual contracts. Contracts are executed by executive branch contracting officers under delegated authority. Congress sets overall funding levels but does not approve individual contract awards.",

    # USD(A&S)
    "Managing day-to-day program execution for all ACAT programs": "Incorrect for USD(A&S). The USD(A&S) is the senior executive responsible for defense acquisition policy, not day-to-day program management. Day-to-day execution is the PM\\'s job. USD(A&S) serves as MDA for ACAT I programs.",
    "Providing milestone decision authority for ACAT I programs to USD(A&S)": "Correct. USD(A&S) serves as the Milestone Decision Authority (MDA) for ACAT I programs \xe2\x80\x94 the most significant acquisition decisions in the DoD portfolio. For ACAT II and III, MDA is delegated to Component Acquisition Executives (CAEs) and PEOs.",
    "Conducting annual budget reviews for the FYDP": "Correct for OSD/CAPE\\'s role. The FYDP (Future Years Defense Program) is the five-year investment plan for DoD programs. Annual reviews are conducted through the PPBE process, with CAPE providing analytical support.",

    # DAES
    "Contractor profit margins and fee structures": "Incorrect for DAES reporting. The Defense Acquisition Executive Summary (DAES) is a quarterly report on major programs covering cost, schedule, and performance. It does not detail contractor profit margins \xe2\x80\x94 that information is proprietary.",
    "Cost and schedule performance (CPI/SPI), technical progress, risk status, and upcoming decision points": "Correct. The DAES reports key program health indicators to OSD and Congress: EVM data (CPI/SPI for ACAT I programs), APB compliance, risk status, upcoming milestones, and program office assessment.",
    "Individual employee performance ratings": "Incorrect. Government program employee performance ratings are a personnel matter \xe2\x80\x94 not reported in program oversight documents. DAES focuses on program-level cost, schedule, and technical performance.",
    "CAPE has authority to cancel programs unilaterally": "Incorrect. CAPE is an analytical office \xe2\x80\x94 it does not have independent authority to cancel programs. CAPE provides analysis and recommendations to USD(A&S) and SECDEF, who have the authority to restructure or terminate programs.",
    "CAPE controls the release of all program funding": "Incorrect. Funding release is controlled through the financial management chain \xe2\x80\x94 OMB, OSD(Comptroller), Service comptrollers. CAPE influences program funding through its analytical role in the PPBE process but does not control funding release.",

    # CURE NOTICE / STOP WORK
    "Issue a stop-work order to the prime contractor immediately": "Incorrect as a first response. A Cure Notice (FAR 49.607) is the appropriate mechanism when a contractor is endangering performance. A Cure Notice gives the contractor typically 10 days to fix the problem before the government takes more drastic action.",
    "Submit certified cost or pricing data for subcontracts over $2M": "Correct. Under TINA (41 U.S.C. 3502), prime contractors must submit certified cost or pricing data for subcontracts over $2M (when the prime contract also requires certified cost data). This flows down to significant subcontracts to ensure cost transparency.",
    "Safeguard Covered Defense Information (CDI) and report cyber incidents within 72 hours": "Correct. DFARS 252.204-7012 requires DoD contractors handling Covered Defense Information (CDI) to: (1) implement NIST SP 800-171 security controls, (2) report cyber incidents to DoD within 72 hours, and (3) preserve images of compromised systems.",
    "Provide small business subcontracting plans": "Correct. FAR 52.219-9 requires large businesses on contracts over $750K to submit a small business subcontracting plan with goals for small business, SDB, WOSB, SDVOSB, HUBZone, and VOSB participation.",

    # OVERSIGHT ORGS (2nd set)
    "The Government Accountability Office (GAO)": "Correct. GAO is the Congressional watchdog that investigates government programs and spending. In defense acquisition, GAO: (1) conducts program assessments, (2) adjudicates bid protests, and (3) investigates acquisition irregularities at Congressional request.",
    "The Defense Contract Audit Agency (DCAA)": "Correct. DCAA audits contractor costs on behalf of all DoD contracting activities. Its mission: ensure the government pays only allowable, allocable, and reasonable costs on cost-type contracts. DCAA provides audit opinions \xe2\x80\x94 the CO makes final determinations.",
    "The Defense Contract Management Agency (DCMA)": "Correct. DCMA is DoD\\'s contract administration arm \xe2\x80\x94 managing contract performance after award. DCMA COs administer contracts, DCMA quality assurance representatives conduct surveillance, and DCMA is the primary EVM oversight organization for programs reporting IPMR/CPR.",

    # SB SUBCONTRACTING
    "Reserve 25% of the contract value for small business subcontractors": "Incorrect. There is no mandatory reservation of contract value for small business subcontractors. The small business subcontracting plan (FAR 52.219-9) establishes goals \xe2\x80\x94 aspirational targets \xe2\x80\x94 not contractual quotas.",
    "Submit a Small Business Subcontracting Plan with goals for various small business categories": "Correct. Large business prime contractors on contracts over $750K must submit a formal Small Business Subcontracting Plan with specific dollar and percentage goals for: small business (SB), SDB, WOSB, HUBZone SB, VOSB, and SDVOSB.",
    "Exclusively use small businesses for all subcontracts": "Incorrect. Large businesses are not required to use small businesses exclusively. The requirement is to establish realistic goals and make good-faith efforts to meet them. Many subcontracts involve specialized capabilities only available from large businesses.",

    # PRIVITY
    "Direct oversight authority \xe2\x80\x94 the PM can issue direction to subcontractors": "Incorrect. There is no privity of contract between the government and subcontractors. The PM cannot issue binding direction to subcontractors. Doing so would be an unauthorized commitment. The PM communicates subcontractor concerns through the prime.",
    "Insight rights through the prime \xe2\x80\x94 the PM can receive data but cannot direct subcontractors independently": "Correct. The government\\'s relationship to subcontractors is indirect \xe2\x80\x94 mediated through the prime contractor. The PM can request subcontractor performance data and assess subcontractor risk, but cannot direct subcontractor work independently. The prime remains responsible for managing its supply chain.",

    # CURE NOTICE (2nd set)
    "The government has found a billing error that needs to be corrected": "Incorrect. Billing errors are addressed through invoice dispute processes (FAR 32.9) or audit findings \xe2\x80\x94 not Cure Notices. A Cure Notice is specifically for performance deficiencies that endanger the contractor\\'s ability to complete the contract.",
    "The contractor has a specified time (typically 10 days) to cure conditions endangering contract performance or face termination": "Correct. A Cure Notice (FAR 49.607) is issued by the CO when the contractor is in danger of defaulting. The notice specifies the failure and gives the contractor typically 10 days to cure the deficiency. Failure to cure may result in termination for default.",
    "The government intends to exercise a contract option": "Incorrect. Contract option exercise notices are separate actions under FAR 17.207. This is unrelated to a Cure Notice.",

    # MAKE VS. BUY
    "Whether the government should produce the item organically or purchase it from industry": "Correct. Make vs. Buy analysis evaluates whether it is more advantageous for the government to perform work organically (government facilities, employees, or depot maintenance) versus contracting with industry. Factors include cost, national security, industrial base health, and core competency considerations.",
    "The comparison of fixed-price vs. cost-type contracts for major subcontracts": "Incorrect. This describes contract type selection analysis \xe2\x80\x94 which is related to but distinct from Make vs. Buy. Make vs. Buy is a sourcing decision (government vs. contractor performance), not a contract type decision.",

    # PRIVITY / SUBCONTRACTOR
    "Bypassing the prime and conducting government-to-subcontractor reviews directly": "Incorrect. The government cannot bypass the prime contractor to conduct independent subcontractor reviews without specific contractual authority. Bypassing the prime violates privity of contract. The PM must work through the prime.",

    # EVM DISCONNECT RISK
    "The program will receive a negative DAES assessment": "Incorrect. A DAES assessment is a trailing indicator \xe2\x80\x94 it reflects problems already visible in data. The primary risk of disconnect between EVM data and program briefings is far more immediate: when the disconnect surfaces at milestone reviews or independent assessments, the program\\'s credibility is severely damaged.",
    "The disconnect will surface at a major milestone review, causing far greater damage than honest early reporting would have": "Correct. The cardinal rule of program management communication: never brief \\'green\\' when the data says \\'red.\\' Disconnects always surface eventually. Early honest disclosure, while uncomfortable, is far less damaging than discovered misrepresentation.",
    "DCMA will issue a surveillance finding for inaccurate EVM reporting": "Correct. DCMA conducts Integrated Baseline Reviews (IBRs) and ongoing EVM surveillance. If DCMA identifies that EVM data is not accurately reflecting actual performance, it will issue a surveillance finding. Repeated findings can result in DCMA recommending the program\\'s EVM system be decertified.",
    "Congressional staffers will request an independent assessment": "Correct. If Congress becomes aware of a significant disconnect between official program reporting and actual performance, Congressional staffers may request an independent assessment \xe2\x80\x94 triggering a CAPE review, a GAO investigation, or Section 809 Panel-type review. Congressional involvement dramatically escalates consequences.",

    # NUNN-MCCURDY
    "$132.25M (25% above current APB of $115M)": "Correct threshold calculation. The Nunn-McCurdy \\'significant\\' breach threshold is 15% above the current APB. The \\'critical\\' breach threshold is 25% above the current APB. For current APB of $115M: significant = $115M \xd7 1.15 = $132.25M; critical = $115M \xd7 1.25 = $143.75M. Breaching these thresholds triggers Congressional notification requirements.",
    "$125M (25% above original APB of $100M)": "Correct for \\'significant\\' Nunn-McCurdy relative to the original APB. 25% above the original APB of $100M = $125M. This represents the \\'significant cost growth\\' threshold above the original baseline. Above this level, USD(A&S) must notify Congress. The \\'critical\\' threshold above original APB is 50% (\xe2\x86\x92 $150M).",
    "$127.5M (15% above current APB)": "Calculation note: 15% above $115M = $132.25M, not $127.5M. Verify specific APB values against 10 U.S.C. 2433 for the program. Use the Nunn-McCurdy worksheet rather than mental math to avoid calculation errors. The exact threshold depends on the specific current APB value for each program.",
    "$140M (25% above restructured baseline)": "Correct for the specific restructured baseline scenario. If the program was restructured with a new APB of $112M, then 25% above restructured = $112M \xd7 1.25 = $140M. Nunn-McCurdy calculations must always reference the specific APB version. Restructured programs reset certain thresholds but retain comparison to the original APB.",

    # CPI ASSESSMENT
    "Normal performance variation \xe2\x80\x94 single-period CPI fluctuations are expected": "Incorrect for a program with three consecutive declining months. Single-period CPI fluctuations are normal. But three consecutive months of declining CPI \xe2\x80\x94 especially past the 20% completion point \xe2\x80\x94 is statistically significant. Sustained CPI decline after 20% completion rarely reverses.",
    "A systemic cost problem that will not self-correct and requires formal PM action": "Correct. Three or more consecutive months of declining CPI indicates a systemic cost problem. The PM must: (1) validate the EAC, (2) identify root causes, (3) implement documented corrective actions, and (4) brief the PEO on the revised completion estimate.",
    "The contractor\\'s EVMS is not DCMA-accepted and the data is unreliable": "Incorrect as a conclusion from CPI trend alone. DCMA acceptance of an EVMS is a separate determination. CPI trend can be analyzed from reported data regardless of EVMS acceptance status. If the EVMS has not been accepted, the data quality concern should be addressed separately.",
    "The program is approaching a significant Nunn-McCurdy breach": "Possibly correct depending on the EAC. A declining CPI trend may or may not be approaching a Nunn-McCurdy breach \xe2\x80\x94 that depends on the magnitude of the CPI, the EAC, and the APB. Nunn-McCurdy breaches require specific cost growth calculations, not just CPI trend analysis.",

    # NON-TESTABLE REQUIREMENTS
    "It violates JCIDS documentation requirements for CDD submission": "Incorrect. A non-testable requirement violates systems engineering best practices, but the primary regulatory framework for testability is the systems engineering process \xe2\x80\x94 not JCIDS documentation requirements per se.",
    "It is untestable \xe2\x80\x94 meaning there is no way to confirm compliance or non-compliance, creating contract disputes and requirements creep": "Correct. A non-testable requirement (e.g., \\'the system shall be user-friendly\\') is a systems engineering deficiency. If there is no defined test method or acceptance criterion, the government and contractor will disagree on whether the requirement has been met \xe2\x80\x94 creating disputes and requirements creep.",
    "It requires CAPE review before it can be included in the system specification": "Incorrect. CAPE review is for cost estimates and program assessments \xe2\x80\x94 not for individual requirements testability. If a requirement is non-testable, the systems engineer and test community flag it during requirements review.",
    "It cannot be incorporated into the contract SOW under FAR guidelines": "Incorrect. Non-testable requirements can appear in contracts \xe2\x80\x94 FAR does not specifically prohibit them. The problem is practical: non-testable requirements create performance disputes, cost overruns, and litigation risk.",

    # PM COMMUNICATION FAILURES
    "They engage CAPE too early, before internal cost analyses are complete": "Incorrect as a primary PM communication failure. Engaging CAPE early (proactively) is generally good practice \xe2\x80\x94 CAPE can provide methodology guidance before its ICE becomes adversarial. The more common failure is waiting too long.",
    "They wait until a problem is visible before engaging upward \xe2\x80\x94 losing the political capital built through proactive communication": "Correct. The most common PM communication failure is reactive rather than proactive stakeholder management. PMs who brief problems only after they become visible lose credibility. PMs who proactively brief emerging risks build the trust that allows them to navigate bad news without program-threatening consequences.",
    "They brief the prime contractor before informing the PEO": "Incorrect. While briefing the prime contractor is appropriate for performance management discussions, the PM\\'s primary reporting obligation is upward \xe2\x80\x94 to the PEO and oversight chain.",
    "They over-communicate minor issues, creating unnecessary alarm in the oversight community": "Incorrect as a primary PM failure. Over-communication of minor issues is far less common than under-communication of major ones. Senior acquisition leaders consistently prefer more frequent, candid communication over surprised discovery of major problems.",
}

with open('client/src/lib/curriculum.ts') as f:
    content = f.read()

lines = content.split('\n')
updated_lines = []
count = 0

for line in lines:
    stripped = line.strip()
    matched = False

    if stripped.startswith("'") and stripped.endswith("',") and '|||' not in stripped:
        inner = stripped[1:-2]

        if inner in DETAILS:
            detail = DETAILS[inner]
            ws = line[:len(line) - len(line.lstrip())]
            new_line = f"{ws}'{inner}|||{detail}',\n"
            updated_lines.append(new_line)
            count += 1
            matched = True

    if not matched:
        updated_lines.append(line + '\n' if not line.endswith('\n') else line)

# Write back
with open('client/src/lib/curriculum.ts', 'w') as f:
    f.write(''.join(updated_lines))

print(f"Added detail to {count} items")
print(f"Items in DETAILS dict: {len(DETAILS)}")

# Check remaining
with open('client/src/lib/curriculum.ts') as f:
    content2 = f.read()
lines2 = content2.split('\n')
plain_bullets = []
for l in lines2:
    s = l.strip()
    if s.startswith("'") and s.endswith("',") and '|||' not in s:
        inner = s[1:-2].strip()
        if inner and len(inner) > 10 and not inner.startswith('http'):
            plain_bullets.append(inner)

print(f"\nRemaining without detail: {len(plain_bullets)}")
for b in plain_bullets[:15]:
    print(f"  - {b[:80]}")
